/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain,type='meaning')=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType:type});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>{const senseMap={loot:[1,2,1,1],lop:[1,1,2,1],lope:[1,1,2,1],lord:[1,2,3,2],lorry:[1,1,2,1],lot:[1,2,3,4],lotion:[1,1,2,1],lottery:[1,1,2,2],loud:[1,2,3,1],lounge:[1,2,3,1],lounger:[1,2,1,2],love:[1,2,3,4],lovelorn:[1,2,1,2],low:[1,2,3,4],lowa:[1,2,1,2],lowland:[1,2,3,1],loyal:[1,1,2,2],lubricate:[1,2,1,2],lubricity:[1,1,1,2],luck:[1,2,1,2],lucky:[1,2,1,2],lucrative:[1,2,1,2],lug:[1,2,2,1],luggage:[1,2,1,2],lukewarm:[1,2,1,2],lull:[1,2,3,1],lumbering:[1,2,2,1],luminous:[1,2,1,2],lump:[1,2,3,3],lunar:[1,2,1,2],lunatic:[1,2,1,2],lunch:[1,2,1,2],lung:[1,2,2,1],lurch:[1,2,1,2],lure:[1,2,3,2]};return D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(senseMap[w]?.[i]||1),type:'辨义与用法'}))});};
P('loosen','A verb formed from loose with the verbal suffix -en, meaning to make less tight or to become less strict.',C('loosen.s1','维修','Before replacing the filter, Mina loosened the metal ring with a small wrench and lifted it away from the pipe.','更换滤芯前，米娜用小扳手拧松金属环，并把它从管子上取下。','Before replacing the filter / Mina loosened the metal ring / with a small wrench / and lifted it away.','loosen 作及物动词，loosen an object 表示使其不再那么紧。','扳手减小金属环的紧度，符合 s1。'),M('He loosened the lid by tightening it until it could no longer turn.','He loosened the lid by turning it until it was no longer tight.','拧紧而无法转动表示 tighter，不是 loosen。'),[Q('What did Mina loosen?','a metal ring','a paper label','a glass of water','句中明确说她用扳手拧松金属环。'),Q('Which action would loosen a tight screw?','turning it counterclockwise','adding glue around its head','pressing it deeper without turning','拧松螺丝会让它逐渐不紧。'),Q('Which sentence uses loosen figuratively?','The new rules loosened the restrictions.','The new rules loosened the blue paint color.','The new rules loosened the calendar date.','loosen 也可表示放宽限制。'),Q('The suffix -en in loosen helps form a?','verb meaning “make loose”','plural noun for a loose object','past tense of lose','-en 在这里构成“使变松”的动词。')]);
P('looseness','Looseness is formed from loose plus -ness, naming a state of being not tight or not firmly controlled.',C('looseness.s1','质量检查','The mechanic found looseness in the wheel bearing, so she replaced it before the car was driven again.','技师发现车轮轴承松动，于是在汽车再次行驶前将其更换。','The mechanic found looseness / in the wheel bearing / so she replaced it / before the car was driven again.','looseness 是不可数性质名词；in 引出松动所在部件。','轴承不够紧固，指物理上的松动。'),M('The inspection praised the looseness of the bolt because it was firmly tightened and could not move.','The inspection flagged the looseness of the bolt because it was not firmly tightened.','牢固拧紧的螺栓不具备 looseness。'),[Q('Looseness in a bearing means it is?','not firmly tight','made of paper','too brightly coloured','looseness 表示不够紧固、存在松动。'),Q('Which inspection result shows looseness?','the wheel shifts slightly on its bearing','the wheel is perfectly fixed in place','the wheel has a new paint stripe','轻微位移说明部件有松动。'),Q('The suffix -ness changes loose into a?','noun for a condition','verb for tightening','plural adjective','-ness 将形容词构成性质名词。'),Q('Which phrase is natural?','looseness in the joint','looseness of the loudly','looseness to run quickly','looseness 常指连接部位不紧固。')]);
P('loot','English loot was borrowed through Hindi lūṭ (“plunder”); it names stolen goods and can also mean to steal them.',[C('loot.s1','冲突后的清点','After the museum was evacuated, staff found that several historic coins had been taken as loot.','博物馆疏散后，工作人员发现几枚历史钱币被当作掠夺物拿走了。','After the museum was evacuated / staff found / that several historic coins / had been taken as loot.','loot 作不可数名词，表示被掠夺的物品；as 引出用途或身份。','钱币在混乱中被非法夺走，符合名词义 s1。'),C('loot.s2','灾后秩序','Police guarded the closed shops overnight so that nobody could loot them after the storm.','警察整夜守着关闭的商店，防止有人在风暴后趁乱洗劫。','Police guarded the closed shops / so that nobody could loot them / after the storm.','loot 作及物动词，后接被洗劫的地点或物品。','风暴后的商店遭趁乱偷抢，符合动词义 s2。')],M('The report called the coins loot even though their owner had lent them to the museum and no one stole them.','The report called the stolen coins loot after investigators confirmed they had been taken without permission.','合法借展的物品不是掠夺物。'),[Q('In the museum report, loot refers to?','goods stolen during disorder','coins bought at a normal shop','labels printed for an exhibit','loot 作名词指被掠夺的物品。'),Q('Which sentence uses loot as a verb?','The gang looted the closed store.','The loot was locked in a cabinet.','The shop displayed a list of prices.','looted 是动词，描述洗劫商店。'),Q('Why did police guard the shops?','to prevent people from stealing goods','to help people borrow exhibits','to count the museum tickets','守卫是为了阻止趁乱抢劫。'),Q('Loot entered English through which language?','Hindi','Finnish','Korean','英语 loot 经由印地语借入。')]);
P('lop','The pruning verb lop is recorded in Old English; its precise deeper history is uncertain, while modern use also allows figurative removal.',[C('lop.s1','园林维护','The gardener lopped two dead branches from the apple tree before they could fall onto the path.','园丁从苹果树上砍去两根枯枝，以免它们掉到小路上。','The gardener lopped / two dead branches / from the apple tree / before they could fall.','lop 作及物动词；lop something from a tree 表示砍去枝条。','枯枝被切除，符合修剪义 s1。'),C('lop.s2','预算调整','The editor lopped several pages from the draft to bring the report within the required length.','编辑从草稿中删去几页，使报告符合规定篇幅。','The editor lopped / several pages / from the draft / to bring the report within the required length.','lop 可比喻删减内容，常用 lop something from。','从草稿删页是比喻性的删减，符合 s2。')],M('The gardener lopped a branch by carefully tying it to the trunk and leaving it attached.','The gardener lopped the branch by cutting it off the tree.','绑住但不切除不构成 lop。'),[Q('What does the gardener lop?','dead branches','ripe apples','the garden path','lop a branch 表示砍去枝条。'),Q('What does the editor lop from the draft?','several pages','the title of the bookshop','a new tree branch','lop 可比喻删减稿件内容。'),Q('Which phrase follows the usual pattern?','lop a branch from a tree','lop a tree with a bookmark','lop at the length of a report','常见搭配是 lop something from something。'),Q('Which action is the literal meaning of lop?','cutting unwanted parts away','watering a tree deeply','measuring a branch carefully','本义是砍去或修剪多余部分。')]);
P('lope','Lope is a verb and noun for an easy, bounding run or the long, relaxed stride used in that run.',C('lope.s1','野生动物','At dawn, the antelope began to lope across the open grassland, covering ground without appearing hurried.','黎明时，羚羊开始轻松大步地穿过开阔草原，跑得不慌不忙。','At dawn / the antelope began to lope / across the open grassland / without appearing hurried.','lope 作不及物动词，常接 across/along 等方向短语。','动物以轻松而有弹性的步幅奔跑，符合 s1。'),M('The antelope loped by taking tiny, rigid steps without lifting its feet.','The antelope loped with long, relaxed, bounding strides.','细小僵硬的步伐与轻松的大步跑相反。'),[Q('How did the antelope move?','with relaxed bounding strides','by crawling under the soil','by standing completely still','lope 指轻松、有弹性地大步跑。'),Q('Which animal might lope across a field?','a horse moving in an easy run','a snail moving almost imperceptibly','a stone lying in the grass','lope 描写动物轻快的大步奔跑。'),Q('Which sentence uses lope as a noun?','The horse settled into a smooth lope.','The horse lope across the field yesterday.','The horse is lope very carefully.','a lope 可指这种轻松的大步跑步姿态。'),Q('A lope usually looks?','easy and bounding','short and motionless','strictly underwater','lope 的步态轻松而有弹性。')]);
P('lopsided','Lopsided combines lop (“hanging down”) with sided and describes something uneven or weighted to one side.',C('lopsided.s1','体育比分','The final score was so lopsided that the losing team had scored only once by halftime.','最终比分悬殊，落后的一队到中场时只得了一分。','The final score / was so lopsided / that the losing team / had scored only once by halftime.','lopsided 作形容词，修饰 score；that 从句说明不均衡程度。','一方得分远少于另一方，比分明显倾斜。'),M('The contest was called lopsided even though both teams scored exactly the same number of points.','The contest was called lopsided because one team scored far more points than the other.','双方得分相同，不构成比分悬殊。'),[Q('A lopsided score is?','very uneven between the sides','exactly equal on both sides','missing from the scoreboard','lopsided 表示一边明显占优、不均衡。'),Q('Which object is lopsided?','a cake leaning heavily to one side','a level table with equal legs','a perfectly round coin','向一侧倾斜的蛋糕呈不均衡状态。'),Q('What does the halftime detail show?','one team was far behind','the game had no score','both teams won equally','只得一分说明双方差距明显。'),Q('Lopsided most nearly means?','unbalanced','transparent','portable','unbalanced 与 lopsided 意思相近。')]);
P('lopsidedness','Lopsidedness is formed from lopsided plus -ness and names a lack of balance or equality.',C('lopsidedness.s1','数据分析','The analyst noted the lopsidedness of the survey because nearly all responses came from one city.','分析员指出这项调查样本不均衡，因为几乎所有回答都来自同一座城市。','The analyst noted / the lopsidedness of the survey / because nearly all responses / came from one city.','lopsidedness 是性质名词；of 引出不均衡的对象。','样本过度集中于一地，缺少代表性。'),M('The survey showed lopsidedness because equal numbers of people from every region responded.','The survey showed lopsidedness because one region supplied nearly all the responses.','各地区人数相等说明样本均衡，而非偏斜。'),[Q('Survey lopsidedness here refers to?','an imbalance in where responses came from','a typo in the survey title','the survey being printed in colour','回答过度集中于一地构成不均衡。'),Q('Which change would reduce the lopsidedness?','recruiting respondents from more regions','removing all responses from other regions','asking only the largest city again','增加其他地区受访者可改善样本平衡。'),Q('The suffix -ness makes lopsidedness a?','noun naming a quality','verb meaning to lean','plural form of lopsided','-ness 把形容词转成性质名词。'),Q('Lopsidedness is closest to?','imbalance','symmetry','permission','该词表示不平衡。')]);
P('lord','Lord comes from Old English hlāford, historically connected with “bread keeper”; it can name a British noble, God, or a powerful master.',[C('lord.s1','英国头衔','The lord addressed the House of Lords before the committee began its debate on the proposed law.','委员会开始辩论拟议法律前，这位勋爵向上议院发表了讲话。','The lord addressed the House of Lords / before the committee began / its debate on the proposed law.','lord 作可数名词，可指英国贵族头衔持有者。','在上议院发言的贵族符合 s1。'),C('lord.s2','宗教文本','In the prayer, the congregation called on the Lord for strength during the difficult season.','在祷告中，会众祈求主在艰难时期赐予力量。','In the prayer / the congregation called on the Lord / for strength / during the difficult season.','宗教义常大写 Lord；call on 引出祈求对象。','祷告中的 Lord 指基督教的上帝。'),C('lord.s3','历史庄园','The villagers owed rent and service to the lord who controlled the estate.','村民必须向掌管庄园的领主缴租并服劳役。','The villagers owed rent and service / to the lord / who controlled the estate.','历史社会语境中 lord 可指拥有支配权的领主。','庄园的控制者符合主人或领主义。')],M('The article called the ordinary tenant a lord because he had no title, land, or authority over anyone.','The article called the estate owner a lord because he held a noble title and controlled the land.','普通租户且无头衔、权力，不符合这里的贵族义。'),[Q('In the House of Lords, a lord is?','a holder of a British noble title','a hired driver of a lorry','a person who repairs a wheel','这里 lord 指贵族头衔持有者。'),Q('In a Christian prayer, the Lord usually means?','God or Christ','a local shopkeeper','a court witness','宗教语境的大写 Lord 指上帝或基督。'),Q('In a medieval estate, the lord was likely?','the person with power over the land','a visitor with no authority','a harvest tool','庄园领主掌管土地并对村民有权力。'),Q('Which spelling convention is common for the deity?','Lord with a capital L','lord with every letter doubled','LORDS as a verb','提及基督教上帝时常大写 Lord。')]);
P('lordly','Lordly is formed from lord plus -ly and describes a manner that seems noble, grand, or superior.',C('lordly.s1','人物描写','The host gave a lordly wave from the balcony, as if the entire square had gathered to greet him.','主人在阳台上傲然挥手，仿佛整个广场的人都是来迎接他的。','The host gave a lordly wave / from the balcony / as if the entire square / had gathered to greet him.','lordly 作形容词修饰 wave；as if 引出夸张的自我姿态。','挥手显得高傲气派，符合 s1。'),M('She made a lordly gesture by apologizing humbly and treating everyone as an equal.','She made a lordly gesture by looking down on the crowd and expecting their attention.','谦逊平等不体现高傲或居高临下。'),[Q('A lordly wave suggests a manner that is?','grand and somewhat superior','shy and barely visible','accidental and unnoticed','lordly 描写气派且带优越感的姿态。'),Q('Which person behaves in a lordly way?','someone who expects everyone to admire him','someone who quietly asks for directions','someone who shares credit equally','期待众人仰慕体现高傲姿态。'),Q('Lordly is formed with which suffix?','-ly','-less','-ment','lord 加 -ly 构成形容词。'),Q('The host’s wave seemed lordly because he acted as if?','the crowd existed to greet him','he had lost his keys','the balcony was broken','他摆出仿佛众人都为他而来的姿态。')]);
P('lore','Lore comes from Old English lār (“teaching, instruction”) and now often means traditional knowledge about a subject or community.',C('lore.s1','地方传统','The guide explained the island’s fishing lore, including the signs sailors used to predict a change in the tide.','导游讲解了岛上的渔业传统知识，包括水手用来预测潮汐变化的征兆。','The guide explained / the island’s fishing lore / including the signs / sailors used to predict a change in the tide.','lore 常作不可数名词，修饰词 fishing 指某领域的传统知识。','关于潮汐征兆的代代相传经验属于 lore。'),M('The guide called it fishing lore although the instructions were newly invented yesterday and had no connection to local practice.','The guide called it fishing lore because sailors had passed the tide signs down through generations.','刚发明且无传统联系的信息不宜称为 lore。'),[Q('Fishing lore is?','traditional knowledge about fishing','a list of new fishing prices','a machine used to raise a boat','lore 指某领域传统积累的知识。'),Q('Which item could belong to sailors’ lore?','a sign traditionally used to predict tides','a brand-new phone advertisement','a random page number','代代相传的潮汐征兆属于传统知识。'),Q('Lore is most often used as a?','mass noun for knowledge','plural verb for learning','unit of boat length','lore 通常作不可数名词。'),Q('Which phrase is natural?','local folklore and fishing lore','lore the boat into the harbour','three lores of oil','fishing lore 是自然搭配。')]);
P('lorry','Lorry is a British English word for a large road vehicle that carries goods; it may also mean one lorry-load.',[C('lorry.s1','公路运输','A lorry delivered refrigerated food to the supermarket before the morning traffic became heavy.','一辆卡车在早高峰车流变大前将冷藏食品送到了超市。','A lorry delivered refrigerated food / to the supermarket / before the morning traffic / became heavy.','lorry 作可数名词，英式英语常用；美式英语常说 truck。','公路运输货物的大型车辆符合 s1。'),C('lorry.s2','货物计量','The farm sent a lorry of apples to the market after the harvest.','收获后，农场向市场运去了一卡车苹果。','The farm sent / a lorry of apples / to the market / after the harvest.','a lorry of 表示一车所载的货物，量词用法。','一辆车所载的一批苹果符合 s2。')],M('The driver loaded a lorry of apples, meaning a single apple carried the weight of the entire vehicle.','The driver loaded a lorry of apples, meaning as many apples as one truck could carry.','a lorry of 表示一车货量，不是一只苹果。'),[Q('What does a lorry carry?','goods by road','passengers beneath the sea','letters inside a book','lorry 是运输货物的大型道路车辆。'),Q('Which word is a common American equivalent of lorry?','truck','lotion','lore','美式英语常用 truck 表示卡车。'),Q('A lorry of apples means?','the amount one lorry can carry','one apple shaped like a vehicle','apples grown beside a road','该结构表示一辆卡车所载的苹果量。'),Q('The lorry arrived before traffic became heavy because?','it was delivering refrigerated food early','it was parked for the night','it carried no goods','语境说明卡车为避开拥堵提前配送。')]);
P('lose','Lose comes from Old English losian (“perish, be lost”) and means to stop having something or fail to win.',C('lose.s1','日常失物','Check the side pocket so you do not lose your passport while changing trains.','换乘时检查一下侧袋，免得把护照弄丢。','Check the side pocket / so you do not lose your passport / while changing trains.','lose 作及物动词，后接遗失的物品；不规则变化 lose–lost。','护照可能不再由旅客持有，符合 s1。'),M('She did not want to loose her passport, so she kept it securely in the zipped pocket.','She did not want to lose her passport, so she kept it securely in the zipped pocket.','loose 是形容词，表示松的；此处需要动词 lose。','confusable'),[Q('What might happen if you lose a passport?','you can no longer find or keep it','it will automatically become a train ticket','it will become a road vehicle','lose 指失去或弄丢某物。'),Q('Choose the correct form: “They ___ the final.”','lost','loosed','losing','lose 的过去式是 lost。','grammar'),Q('Which spelling is the verb meaning “misplace”?','lose','loose','louse','lose 是动词；loose 是形容词。','confusable'),Q('A team can lose a match by?','failing to win it','repairing the stadium','changing its uniform colour','lose 也表示比赛未能获胜。')]);
P('loss','Loss is the noun related to lose, naming the fact or amount of something lost and also the failure to win.',C('loss.s1','财务报告','The company reported a loss after repair costs exceeded the income from the damaged warehouse.','维修费用超过受损仓库带来的收入后，公司报告了亏损。','The company reported a loss / after repair costs exceeded the income / from the damaged warehouse.','loss 作可数名词，a loss；after 引出亏损原因。','收入低于支出，形成财务损失。'),M('The company reported a loss even though its income exceeded every cost and its profit rose sharply.','The company reported a loss because its costs exceeded its income.','收入超过所有成本且利润上升，与亏损相反。'),[Q('A company reports a financial loss when?','costs exceed income','income exceeds all costs','it changes its logo','收入低于支出时会出现亏损。'),Q('Which word is the noun related to lose?','loss','loose','losingness','loss 是 lose 的相关名词。'),Q('“The team suffered a loss” means the team?','failed to win','changed its coach','lost its equipment permanently','比赛语境中 loss 指失败。'),Q('Which phrase is correct?','a loss of income','a loose of income','a lost of income','标准名词搭配是 a loss of。','grammar')]);
P('lost','Lost is the irregular past and past participle of lose; as an adjective it means missing or unable to find one’s way.',C('lost.s1','旅行迷路','The hikers were lost in the fog, so they stayed together and used a compass to locate the trail.','徒步者在浓雾中迷了路，于是留在一起并用指南针寻找小径。','The hikers were lost / in the fog / so they stayed together / and used a compass to locate the trail.','lost 作表语形容词；be lost 表示不知道身在何处或找不到方向。','徒步者无法辨认路线，符合迷路义。'),M('The hikers were lost, meaning they knew their exact position and followed the marked trail without difficulty.','The hikers were lost, meaning they did not know their position or how to reach the trail.','清楚位置且顺利前进并非迷路。'),[Q('The hikers were lost means they?','could not find their way','had already reached the campsite','had misplaced the compass but knew the route','lost 描述无法辨认方向。'),Q('Lost is the past form of which verb?','lose','loose','loosen','lose 的过去式和过去分词都是 lost。'),Q('What did the hikers use to locate the trail?','a compass','a lorry','a lotion bottle','语境明确说他们使用指南针。'),Q('Which sentence uses lost to mean “missing”?','The lost key was found under the desk.','The key is lost in translation from English.','The key losts beside the desk.','lost 可形容找不到的物品。')]);
P('lost pet','Lost pet is a compound noun for a domestic animal that has become separated from its owner and cannot be found.',C('lost pet.s1','社区公告','A volunteer posted a photo of the lost pet, a small brown dog last seen near the library, on the neighbourhood board.','一名志愿者在社区公告栏贴出了走失宠物的照片：那是一只棕色小狗，最后一次出现在图书馆附近。','A volunteer posted a photo / of the lost pet / a small brown dog / last seen near the library.','lost 修饰 pet；公告提供特征和最后出现地点。','宠物与主人走散且正在寻找，符合词义。'),M('The notice called the dog a lost pet even though it was safely at home with its owner.','The notice called the dog a lost pet because it had wandered away and its owner could not find it.','已在家且与主人团聚的狗不属于走失宠物。'),[Q('A lost pet is an animal that?','has become separated from its owner','has just been adopted and is at home','is being sold at a market','lost pet 指与主人走散、尚未找到的宠物。'),Q('What detail helps identify the dog?','it is a small brown dog last seen near the library','it is a blue bus at the station','it is a wild fish in the sea','公告给出体型、颜色和地点。'),Q('Where did the volunteer post the notice?','on the neighbourhood board','inside the dog’s food bowl','on a train ticket','语境说公告贴在社区栏上。'),Q('Which phrase has the same meaning?','a missing animal belonging to someone','a pet sleeping beside its owner','a wild animal living in a forest','lost pet 可改述为某人走失的宠物。')]);
P('lost-and-found','Lost-and-found combines lost and found to name a place where misplaced property is kept for its owner to reclaim.',C('lost-and-found.s1','校园服务','Nora checked the school lost-and-found after she noticed that her gloves were missing from the classroom.','诺拉发现手套不在教室后，去学校失物招领处查看。','Nora checked / the school lost-and-found / after she noticed / that her gloves were missing.','lost-and-found 作复合名词，常作 lost-and-found office/desk 的省略形式。','失物招领处用于寻找丢失物品，符合 s1。'),M('The school sent unclaimed keys to the lost-and-found so that nobody could ever reclaim them.','The school sent unclaimed keys to the lost-and-found so their owners could reclaim them.','失物招领处的目的正是让失主认领物品。'),[Q('A lost-and-found is a place to?','look for misplaced property','buy new gloves','report a weather forecast','lost-and-found 用于寻找并认领失物。'),Q('Why did Nora visit it?','her gloves were missing','she wanted to borrow a classroom','she needed a new school timetable','她发现手套不见了。'),Q('Which item belongs in a school lost-and-found?','a key left in the library','a meal ordered from a café','a lesson written on the board','失物招领处收存遗落的钥匙。'),Q('The phrase is formed from?','lost and found','loud and low','loose and lord','该复合词由 lost 与 found 构成。','word-formation')]);
P('lot','Lot comes from Old English hlot (“portion, share”); it can mean a large amount, a plot of land, an auction group, or one’s fate.',[C('lot.s1','日常数量','We still have a lot of work to finish, so the team divided the remaining tasks before lunch.','我们还有很多工作要完成，所以团队在午饭前分配了剩余任务。','We still have a lot of work / to finish / so the team divided / the remaining tasks.','a lot of 可修饰不可数名词 work；lot 在此表示大量。','工作量很大，符合数量义 s1。'),C('lot.s2','土地规划','The council approved a new building on the vacant lot beside the railway station.','市政委员会批准在火车站旁的空地上建一栋新楼。','The council approved a new building / on the vacant lot / beside the railway station.','lot 作可数名词，指一块划定的土地。','车站旁的空地是地块，符合 s2。'),C('lot.s3','拍卖现场','Lot 18 in the auction was a set of handwritten letters from the explorer.','拍卖中的第18号拍品是一组探险家的手写信件。','Lot 18 in the auction / was a set of handwritten letters / from the explorer.','拍卖用法中 lot 指单件或一组作为一个单位出售的拍品。','一组信件被作为同一拍卖单元出售。'),C('lot.s4','人生境遇','Although her lot was difficult, she remained generous to the neighbours who helped her.','尽管她的处境艰难，她仍慷慨对待帮助过她的邻居。','Although her lot was difficult / she remained generous / to the neighbours / who helped her.','one’s lot 是较书面的表达，指某人所处的命运或境遇。','困难生活处境符合 s4。')],M('The notice described the tiny garden as a lot of work, although it meant a parcel of land for sale.','The notice described the tiny garden as a vacant lot, a parcel of land available for sale.','指地块应说 a lot，而 a lot of work 表示许多工作。','usage'),[Q('In “a lot of work,” lot means?','a large amount','a parcel of land','an auction number','a lot of 后接不可数名词表示大量。'),Q('A vacant lot near a station is?','an empty plot of land','a large amount of noise','a lost ticket','vacant lot 指空地。'),Q('At an auction, Lot 18 is?','a sale unit or item','the eighteenth road','the buyer’s final address','lot 可指一个拍卖品或一组拍品。'),Q('“Her lot was difficult” means her?','life situation was difficult','land plot was empty','auction item was expensive','one’s lot 可指命运或处境。')]);
P('loth','Loth is a less common spelling variant of loath, an adjective meaning reluctant or unwilling.',C('loth.s1','工作态度','Though loth to interrupt the meeting, Priya raised her hand because the safety figures were wrong.','尽管不愿打断会议，普里娅还是举手了，因为安全数据有误。','Though loth to interrupt the meeting / Priya raised her hand / because the safety figures were wrong.','loth 常接不定式，表示不情愿做某事；loath 是更常见拼法。','她不愿打断但仍有必要发言，体现 reluctant。'),M('He was loth to leave, so he eagerly rushed out before the guests had arrived.','He was loth to leave, so he reluctantly stayed until the meeting ended.','急切离开与 loth 所表达的不情愿相矛盾。'),[Q('Someone loth to speak is?','reluctant to speak','eager to speak first','unable to understand speech','loth 表示不愿意或勉强。'),Q('Which word is the more common spelling variant?','loath','loud','loose','loath 是更常见拼法。'),Q('Which construction is natural?','loth to interrupt','loth for interrupt','loth with interrupting','loth 常用 loth to do something。','grammar'),Q('Why did Priya speak despite being loth?','the safety figures were wrong','she wanted to stop the meeting for fun','she had already left the room','安全数据错误促使她尽管不情愿仍发言。')]);
P('lotion','Lotion comes from Latin lotio (“washing”); it is a liquid or cream applied to the skin, often for cleansing or soothing.',[C('lotion.s1','日常护肤','After washing her hands, Amina applied a fragrance-free lotion to stop the skin from becoming dry.','洗手后，阿米娜涂上无香型润肤乳，以免皮肤变干。','After washing her hands / Amina applied / a fragrance-free lotion / to stop the skin from becoming dry.','lotion 作可数名词，apply lotion to the skin；a 可标明一种产品。','护肤乳用于滋润皮肤，符合 s1。'),C('lotion.s2','药物护理','The pharmacist explained how to apply the medicated lotion to the rash twice a day.','药剂师解释了如何每天两次将药用洗剂涂在皮疹处。','The pharmacist explained / how to apply the medicated lotion / to the rash / twice a day.','medicated lotion 指含药液剂；apply A to B 表示涂于患处。','用于皮疹的药用制剂符合 s2。')],M('She rubbed lotion into her skin to remove the dryness, but the bottle contained a dry powder that could not be spread.','She rubbed lotion into her skin to remove the dryness; it was a liquid or cream made to spread on skin.','普通 lotion 是可涂抹的液体或乳液，不是干粉。'),[Q('What is lotion usually applied to?','the skin','a wooden floor','a loudspeaker','lotion 是涂在皮肤上的液体或乳液。'),Q('Why did Amina use fragrance-free lotion?','to prevent her skin from becoming dry','to lubricate a lorry engine','to clean a lost coin','语境明确说她用它防止皮肤干燥。'),Q('A medicated lotion is used to?','treat a skin condition','measure a plot of land','polish a musical instrument','药用洗剂用于治疗皮肤问题。'),Q('Which verb commonly goes with lotion?','apply','auction','lope','常见搭配为 apply lotion。','collocation')]);
P('lots','Lots is the plural of lot and, in the phrase lots of, an informal way to say “a large number or amount.”',C('lots.s1','旅行见闻','We saw lots of wildflowers along the trail after the spring rain.','春雨过后，我们沿着小径看到了许多野花。','We saw lots of wildflowers / along the trail / after the spring rain.','lots of 可接复数可数名词；在口语中表示许多。','wildflowers 数量很多，符合 s1。'),M('They saw lots of wildflower, referring to one single flower growing by the trail.','They saw lots of wildflowers growing along the trail.','lots of 后面的可数名词通常用复数。','grammar'),[Q('“Lots of wildflowers” means?','many wildflowers','one rare flower','no flowers at all','lots of 表示数量很多。'),Q('Which noun form follows lots of in the example?','the plural count noun wildflowers','the singular count noun flower','the verb flowering','lots of 后的可数名词用复数。','grammar'),Q('Which phrase is most natural?','lots of rain','lots rain','a lots of rain','lots of 后可接不可数名词 rain。','grammar'),Q('Lots is the plural of which noun?','lot','lotion','loth','lots 是 lot 的复数形式。')]);
P('lottery','Lottery came through French loterie from Italian lotteria, a game in which chance determines the winning ticket; it also describes a luck-dependent outcome.',[C('lottery.s1','公益抽奖','The school held a charity lottery, and the winning ticket was drawn publicly at the end of the fair.','学校举办了一场慈善抽奖，并在集市结束时公开抽出了中奖彩票。','The school held a charity lottery / and the winning ticket / was drawn publicly / at the end of the fair.','lottery 作可数名词，常与 ticket 和 draw 连用。','中奖号码由随机抽取决定，符合抽彩义 s1。'),C('lottery.s2','人生机会','Getting a seat on the last train felt like a lottery because the queue moved unpredictably.','能坐上末班车简直像碰运气，因为队伍的进度难以预料。','Getting a seat on the last train / felt like a lottery / because the queue moved unpredictably.','a lottery 可比喻结果主要取决于运气的事。','能否上车不可预测，符合比喻义 s2。')],M('The ticket was called a lottery winner before any numbers were drawn and while every ticket was guaranteed the same prize.','The ticket won the lottery when its number matched the number drawn at random.','号码尚未抽出，不能确定彩票中奖。'),[Q('How was the winning ticket selected?','it was drawn by chance','the oldest ticket automatically won','the school chose the neatest handwriting','lottery 的抽奖结果由机会或随机抽取决定。'),Q('Calling the last-train queue a lottery suggests?','the outcome depended unpredictably on luck','everyone had a reserved seat','the train sold numbered prizes','比喻义表示结果难以预测、仰赖运气。'),Q('Which phrase is common?','buy a lottery ticket','drive a lottery to the station','wear a lottery on your hand','彩票活动中的常见搭配是买 lottery ticket。'),Q('In the original sense, a lottery is a?','game with prizes decided by drawn numbers','fixed salary paid every month','vehicle for carrying goods','定义说奖品由抽出的号码决定。')]);
P('lotus','Lotus is the classical plant name transmitted into English through Latin lotus and Greek lōtos; it names an aquatic plant with large flowers.',C('lotus.s1','池塘生态','A white lotus opened above the pond while its broad leaves floated flat on the water.','一朵白莲在池塘水面上开放，宽大的叶片平铺漂浮着。','A white lotus opened / above the pond / while its broad leaves / floated flat on the water.','lotus 作可数名词；while 引出花朵开放时叶片的状态。','水生植物和水面上的花叶符合莲花义。'),M('The botanist identified the lotus as a desert cactus whose roots never grow near water.','The botanist identified the lotus as an aquatic plant growing in the pond.','lotus 是水生植物，不是远离水源的沙漠仙人掌。'),[Q('Where does the lotus in the scene grow?','in a pond','inside a dry desert cave','on a lorry roof','lotus 是生长在水面的水生植物。'),Q('What happened to the white lotus?','it opened above the water','it drove through the pond','it turned into a loudspeaker','语境写到白莲在池塘上开放。'),Q('Which feature is associated with the lotus here?','broad floating leaves','metal wheels','a numbered ticket','莲叶宽大并漂浮在水面上。'),Q('Lotus is the name of a?','flowering aquatic plant','vehicle used for freight','skin-cleaning lotion','词条定义为水生开花植物。')]);
P('loud','Loud comes from Old English hlūd (“noisy, resounding”); it describes high volume and, in another sense, colours that are too bright.',[C('loud.s1','公共交通','The announcement was loud enough for passengers at the far end of the platform to hear it clearly.','广播声音足够大，站台另一端的乘客也能听清。','The announcement was loud enough / for passengers at the far end / of the platform / to hear it clearly.','loud 作表语形容词；loud enough to do 表示声音足以让人听见。','广播音量大且清晰可闻，符合 s1。'),C('loud.s2','服饰选择','He changed the loud orange jacket for a plain coat before the formal dinner.','正式晚宴前，他把那件颜色刺眼的橙色夹克换成了素色外套。','He changed the loud orange jacket / for a plain coat / before the formal dinner.','loud 可修饰颜色或衣物，表示过于鲜艳、俗艳。','橙色过于醒目，不适合正式场合。'),C('loud.s3','朗读练习','Please read the final paragraph loud enough for the students in the back row to follow.','请把最后一段读得足够响，让后排学生也能听懂。','Please read the final paragraph / loud enough / for the students in the back row / to follow.','口语中 loud 也可作副词，表示大声地。','大声朗读以便后排听见，符合副词义 s3。')],M('She wore a loud grey suit that blended into the background and attracted nobody’s attention.','She wore a loud orange suit that stood out and drew attention.','低调不显眼的灰色套装不符合颜色义的 loud。'),[Q('The announcement was loud enough means it?','could be heard clearly at a distance','was too quiet to notice','had no sound at all','loud enough 表示音量足以听见。'),Q('A loud orange jacket is?','very bright and attention-catching','quiet when spoken aloud','a large road vehicle','颜色义的 loud 表示过分鲜艳。'),Q('“Read it loud” uses loud as?','an adverb meaning at high volume','a noun meaning a ticket','a verb meaning to lower','口语里 loud 可作副词，修饰 read。'),Q('Which setting suits a loud orange jacket less?','a formal dinner','a bright summer festival','a costume party','鲜艳服饰在正式晚宴上显得不合适。')]);
P('loudly','Loudly is formed from loud plus -ly and means in a way that produces a high volume of sound.',C('loudly.s1','教室讨论','The teacher asked the pupils not to speak so loudly while another class was taking an exam next door.','隔壁班正在考试，老师因此请学生们不要说得那么大声。','The teacher asked the pupils / not to speak so loudly / while another class / was taking an exam next door.','loudly 是副词，修饰 speak；not so loudly 表示降低音量。','说话音量会影响隔壁考试，符合 s1。'),M('The pupils spoke loudly by whispering so softly that nobody in the room could hear them.','The pupils spoke loudly, and their voices could be heard across the room.','无人听见的耳语不是大声说话。'),[Q('If pupils speak loudly, they speak?','at a high volume','without making any sound','only in written notes','loudly 表示响亮地、大声地。'),Q('What did the teacher want the pupils to do?','lower their speaking volume','start another examination','leave the building permanently','老师要求他们不要说得那么响。'),Q('The suffix -ly makes loudly an?','adverb','plural noun','past-tense verb','-ly 在此构成副词。','word-formation'),Q('Which phrase is grammatical?','speak loudly','loudly speakings','a loudly voice','loudly 修饰动词 speak。','grammar')]);
P('loudness','Loudness is the noun formed from loud plus -ness and refers to how strong or high in volume a sound is.',C('loudness.s1','声学测量','The sound engineer reduced the loudness of the alarm so it remained audible without startling nearby patients.','音响师降低了警报的响度，使其仍能听见又不至于惊吓附近的病人。','The sound engineer reduced / the loudness of the alarm / so it remained audible / without startling nearby patients.','loudness 作不可数名词，of 引出声音来源。','调低警报的声音强度而保持可闻，符合 s1。'),M('The loudness of the alarm was measured as high even though no sound was produced.','The loudness of the alarm was measured while it sounded at a high volume.','完全没有声音时，无法说音量很高。'),[Q('Loudness measures?','how strong a sound is','how far a road runs','how bright a printed letter looks','loudness 指声音的响度。'),Q('Why did the engineer reduce the alarm’s loudness?','to avoid startling nearby patients','to make the alarm impossible to hear','to increase the room temperature','降低音量是为了避免惊吓病人。'),Q('Loudness is formed from loud with?','-ness','-able','-ment','loud 加 -ness 构成表示性质的名词。','word-formation'),Q('Which unit-related phrase makes sense?','the loudness of a sound','the loudness of a kilometre','the loudness of a passport number','loudness 描述声音，不描述长度或号码。')]);
P('loudspeaker','Loudspeaker combines loud and speaker and names a device that converts an electrical signal into amplified sound.',C('loudspeaker.s1','应急广播','A battery-powered loudspeaker allowed the rescue team to give instructions across the crowded field.','电池供电的扬声器让救援队能向拥挤的场地广播指令。','A battery-powered loudspeaker allowed the rescue team / to give instructions / across the crowded field.','loudspeaker 作可数名词；allow someone to do 表示使某人能够做某事。','设备将声音放大并传播给远处人群。'),M('The team used a loudspeaker to make its instructions quieter and impossible to hear.','The team used a loudspeaker to amplify its instructions for the crowd.','扬声器用于放大声音，不是让声音更小、更难听见。'),[Q('What does a loudspeaker do?','broadcasts or amplifies sound','stores refrigerated food','measures the height of a building','loudspeaker 用来广播或放大声音。'),Q('Why did the rescue team use one?','to reach people across a crowded field','to keep its instructions private','to repair the field’s battery','它使救援队的指令能传到人群中。'),Q('Which two words form loudspeaker?','loud + speaker','lotion + keeper','low + sleeper','该复合词由 loud 和 speaker 构成。','word-formation'),Q('Which sentence is natural?','The loudspeaker carried her voice across the hall.','She loudspeakered the chair into a room.','The loudspeaker drank the announcement.','扬声器可把声音传到大厅另一端。')]);
P('lounge','Lounge is recorded in English for a place or manner of relaxing; its historical derivation is uncertain, so no deeper root is asserted here.',[C('lounge.s1','机场候机','We waited in the airport lounge, where passengers could sit comfortably while their flight was delayed.','航班延误时，我们在机场休息室等候，旅客可以在那里舒适地坐着。','We waited / in the airport lounge / where passengers could sit comfortably / while their flight was delayed.','lounge 作可数名词，机场休息室用于等候或放松。','旅客在公共休息室等候，符合 s1。'),C('lounge.s2','英式家居','The family watched a film together in the lounge after dinner.','晚饭后，一家人在客厅一起看电影。','The family watched a film / together in the lounge / after dinner.','英式英语中 lounge 可指家里的客厅。','家庭休闲空间符合 s2。'),C('lounge.s3','慵懒倚靠','Two students lounged on the steps after class, talking slowly and making no effort to hurry.','下课后，两名学生懒洋洋地倚坐在台阶上，慢慢聊天，一点也不着急。','Two students lounged / on the steps / after class / talking slowly.','lounge 作不及物动词，常与 on/around 连用，表示懒散地坐、躺或闲逛。','悠闲倚坐不急于行动，符合 s3。')],M('Passengers waited in the airport lounge, a runway where aircraft accelerate before take-off.','Passengers waited in the airport lounge, a room where they could sit while waiting for their flight.','lounge 是室内休息空间，不是飞机跑道。'),[Q('An airport lounge is a place where passengers can?','wait or relax indoors','load fish into a pond','buy a house plot','机场 lounge 是供乘客休息、等候的房间。'),Q('In British home vocabulary, the lounge is the?','living room','airport runway','skin cream','英式用法中 lounge 可指家里的客厅。'),Q('Students who lounge on steps are?','sitting or relaxing in an unhurried way','running a timed race','repairing the steps','动词 lounge 描写慵懒放松地坐靠。'),Q('Which sentence uses lounge as a noun?','They met in the hotel lounge.','They lounge the hotel into a new wing.','They loudly the hotel.','in the hotel lounge 中 lounge 是地点名词。')]);
P('lounger','Lounger is formed from lounge plus -er and can mean a person who idles or a long reclining chair.',[C('lounger.s1','行为描写','The supervisor called him a lounger because he spent each shift leaning on the counter instead of serving customers.','主管称他是个游手好闲的人，因为他每个班次都靠在柜台上，而不为顾客服务。','The supervisor called him a lounger / because he spent each shift / leaning on the counter / instead of serving customers.','lounger 作人称名词，指懒散消磨时间、少做事的人。','他不工作而闲靠柜台，符合 s1。'),C('lounger.s2','庭院家具','We unfolded a padded lounger beside the pool so Dad could recline in the afternoon sun.','我们在泳池旁展开一张软垫躺椅，让爸爸可以在午后阳光下斜躺休息。','We unfolded / a padded lounger / beside the pool / so Dad could recline.','lounger 也指可斜躺的长椅；recline 描述其使用方式。','泳池边供斜躺的家具符合 s2。')],M('They bought a lounger for the garden, but it was a person hired to water plants rather than a reclining chair.','They bought a garden lounger, a chair designed for reclining outdoors.','购买的庭院家具应是躺椅，不是人。'),[Q('A workplace lounger is someone who?','idles instead of doing much work','repairs a loudspeaker','wins every lottery','lounger 的人称义指游手好闲的人。'),Q('A garden lounger is a?','chair for reclining','person who owns a garden','lottery ticket','家具义指可供斜躺的长椅。'),Q('Why did they place the lounger by the pool?','so someone could recline in the sun','to amplify music over the water','to store lost luggage','泳池旁放置躺椅供人斜躺休息。'),Q('Which formation is correct?','lounge + -er','loud + -ness','lot + -ish','lounger 由 lounge 加 -er 构成。','word-formation')]);
P('loutish','Loutish is formed from lout plus -ish and describes crude, aggressive, or boorish behaviour.',C('loutish.s1','公共礼仪','His loutish behaviour at the restaurant—shouting at the staff and throwing a menu—embarrassed his friends.','他在餐馆里的粗野举止——对员工大喊并扔菜单——让朋友们很难堪。','His loutish behaviour at the restaurant / shouting at the staff / and throwing a menu / embarrassed his friends.','loutish 作形容词修饰 behaviour；破折号内举出具体表现。','大喊并扔东西体现粗鲁且有攻击性的行为。'),M('The guests praised his loutish manners because he spoke courteously and thanked every server.','The guests criticized his loutish manners because he shouted at servers and threw a menu.','礼貌致谢不属于粗野无礼。'),[Q('Loutish behaviour is?','crude and boorish','quietly generous','carefully scientific','loutish 表示粗野、没礼貌。'),Q('Which action is loutish in the restaurant?','shouting at staff and throwing a menu','thanking the server politely','waiting patiently for a table','对员工喊叫并扔菜单属于粗野行为。'),Q('Which word is closest to loutish?','boorish','lucid','luminous','boorish 同样表示粗鲁无礼。'),Q('The suffix -ish here helps form an?','adjective describing behaviour','adverb showing time','plural for a person','lout 加 -ish 构成形容词。','word-formation')]);
P('love','Love developed from Old English lufu/lufian and names deep affection or liking; as a verb it means to care for or like very much, and in tennis zero.',[C('love.s1','家庭关系','Her love for her younger brother showed in the patient way she helped him practise reading each evening.','她对弟弟的爱体现在每天晚上耐心地帮他练习阅读。','Her love for her younger brother / showed / in the patient way / she helped him practise reading.','love 作名词，love for someone 表示对某人的深厚关爱。','长期耐心帮助体现亲情。'),C('love.s2','兴趣爱好','His love of old maps led him to visit the archive every weekend.','他对旧地图的喜爱使他每个周末都去档案馆。','His love of old maps / led him / to visit the archive / every weekend.','love of something 可指强烈爱好或兴趣。','经常去档案馆体现对地图的喜爱。'),C('love.s3','喜爱活动','Many children love building small models because each new design gives them a fresh challenge.','许多孩子喜欢制作小模型，因为每一种新设计都会带来新的挑战。','Many children love building small models / because each new design / gives them / a fresh challenge.','love 作及物动词，可接名词或动名词，表示很喜欢。','孩子们非常喜欢制作模型，符合动词喜爱义。'),C('love.s4','网球计分','The scoreboard showed 40–love, so the server had won four points while the receiver had won none.','记分牌显示40比0，因此发球方赢了四分，而接球方一分未得。','The scoreboard showed 40–love / so the server had won four points / while the receiver / had won none.','网球中 love 是零分，不表示情感。','记分牌上的 love 表示接球方得分为零。')],M('The tennis score was 30–love, meaning both players had scored thirty points each.','The tennis score was 30–love, meaning one player had thirty points and the other had none.','网球计分中的 love 表示零分，不表示三十分。'),[Q('Love for a family member is?','deep affection and care','a road vehicle','a kind of body lotion','love 的情感义表示深厚关爱。'),Q('His love of maps means he?','has a strong interest in maps','is afraid to look at maps','sells every map he finds','love of 可指强烈兴趣。'),Q('“Children love building models” uses love as?','a verb meaning enjoy very much','a noun meaning zero','an adjective meaning low','love 可作动词，后接动名词。'),Q('In tennis, love means?','zero points','a tied score of forty','the winning serve','网球计分中 love 表示零分。')]);
P('love affair','Love affair combines love and affair; it can mean a romantic or sexual relationship, or an intense enthusiasm for something.',C('love affair.s1','新闻报道','The actor refused to discuss the private love affair that tabloids claimed had begun during filming.','这位演员拒绝谈论小报声称在拍摄期间开始的那段私人恋情。','The actor refused to discuss / the private love affair / that tabloids claimed / had begun during filming.','love affair 作可数复合名词，可指恋情；claimed 引出未经证实的报道。','报道谈论两个人之间的恋爱关系。'),M('The article called it a love affair even though the two people had never met or communicated.','The article called it a love affair because the pair had a romantic relationship.','从未相识或交流的人之间没有恋情。'),[Q('A love affair usually involves?','a romantic relationship','a traffic collision','a business invoice','love affair 指恋情。'),Q('What kind of source made the claim in the example?','tabloids','a weather station','a school attendance chart','例句中是小报声称这段恋情开始于拍摄期间。'),Q('Which expression is natural?','a private love affair','a love affair of the loudspeaker volume','a love affair three metres long','private love affair 是自然搭配。'),Q('A love affair differs from “love of maps” because it refers to?','a relationship between people','an interest in collecting paper','a tennis score of zero','love affair 主要指恋爱关系。')]);
P('love story','Love story combines love and story and means a narrative centred on two people’s romantic relationship.',C('love story.s1','影视介绍','The film is a love story about two musicians whose careers take them to different cities.','这部电影讲述一对音乐家的爱情故事，两人的事业让他们去了不同的城市。','The film is a love story / about two musicians / whose careers take them / to different cities.','love story 作可数复合名词，about 引出故事人物或主题。','情节核心是两位音乐家的恋爱关系。'),M('The reviewer called it a love story even though the film contained no relationship or affection between its characters.','The reviewer called it a love story because its plot follows a couple’s romantic relationship.','故事没有人物之间的恋爱关系便不符合该体裁。'),[Q('A love story is a narrative centred on?','a romantic relationship','the repair of a truck','a number-drawing contest','love story 指以恋爱关系为中心的叙事。'),Q('Who are the central characters in the example?','two musicians','two ticket inspectors','two gardeners','例句里的主人公是两位音乐家。'),Q('Which phrase best describes the film?','a story about a couple’s relationship','a manual for loudspeakers','a history of road signs','爱情故事围绕恋爱关系展开。'),Q('Which two nouns form love story?','love + story','loud + speaker','lost + pet','该复合名词由 love 和 story 组成。','word-formation')]);
P('loveliness','Loveliness is formed from lovely plus -ness and names the quality of being beautiful, charming, or pleasant.',C('loveliness.s1','自然景色','The guide paused to admire the loveliness of the valley in the early morning light.','导游停下来欣赏山谷在清晨光线中的美丽。','The guide paused / to admire the loveliness of the valley / in the early morning light.','loveliness 作不可数性质名词，of 引出美丽的对象。','山谷景色令人欣赏，体现美丽宜人的性质。'),M('The guide praised the valley’s loveliness although it was unpleasant, ugly, and distressing to look at.','The guide praised the valley’s loveliness because its scenery was beautiful and pleasant.','丑陋难看的景色不能支持这里的“美丽”评价。'),[Q('Loveliness is the quality of being?','beautiful or charming','difficult to lift','impossible to hear','loveliness 指美丽、可爱宜人的性质。'),Q('What did the guide admire?','the valley in morning light','a missing passport','a lottery ticket','导游欣赏的是晨光中的山谷。'),Q('Loveliness is related to which adjective?','lovely','loud','low-risk','loveliness 由 lovely 加 -ness 构成。','word-formation'),Q('Which phrase is natural?','the loveliness of the garden','the loveliness to drive a lorry','three lovelinesses of rain','常用结构是 the loveliness of something。')]);
P('lovelorn','Lovelorn combines love and forlorn and describes someone sad because love is absent, unreturned, or has ended.',[C('lovelorn.s1','失恋情绪','The lovelorn singer wrote a quiet song after the relationship ended, but she later moved on with her life.','恋情结束后，这位失恋的歌手写了一首安静的歌，但之后她重新开始了生活。','The lovelorn singer wrote / a quiet song / after the relationship ended / but she later moved on.','lovelorn 作定语形容词修饰 singer，表达因恋情结束而悲伤。','恋情终止带来伤心，符合失恋义 s1。'),C('lovelorn.s2','单恋心境','He felt lovelorn because his affection for a colleague was not returned.','由于对同事的感情没有得到回应，他感到相思而忧伤。','He felt lovelorn / because his affection for a colleague / was not returned.','lovelorn 也可形容爱意未获回应的人。','单恋得不到回应符合 s2。')],M('She was lovelorn because her partner had returned her affection and their relationship was thriving.','She was lovelorn because the relationship had ended and she still missed her former partner.','恋情顺利且感情得到回应，与 lovelorn 的伤心含义不符。'),[Q('A lovelorn person is sad because?','love is absent, unreturned, or has ended','a loudspeaker is broken','a lottery ticket is missing','lovelorn 描述因爱情受挫而忧伤。'),Q('His affection was not returned means?','the other person did not feel the same way','the other person sent him a gift','the couple had already married','没有得到回应说明是单恋。'),Q('What did the singer do after the relationship ended?','wrote a quiet song','bought a lorry','opened a lost-and-found','她失恋后写歌。'),Q('Which phrase is natural?','a lovelorn character in the novel','a lovelorn loudness of music','a lovelorn five kilometres','lovelorn 常修饰人或人物。')]);
P('lovely','Lovely developed from love plus -ly and describes someone or something very pleasant, beautiful, or enjoyable.',C('lovely.s1','周末活动','We had a lovely afternoon by the lake, with warm sunshine and enough time to talk.','我们在湖边度过了愉快的下午，阳光温暖，也有充足时间聊天。','We had a lovely afternoon / by the lake / with warm sunshine / and enough time to talk.','lovely 作形容词修饰 afternoon；with 短语补充愉快的原因。','舒适阳光和闲谈使下午令人愉快。'),M('They called the afternoon lovely even though the storm ruined the picnic and everyone was miserable.','They called the afternoon lovely because the weather was pleasant and everyone enjoyed the picnic.','风暴毁掉野餐且众人难受，不支持“愉快”的评价。'),[Q('A lovely afternoon is?','very pleasant or enjoyable','extremely noisy in volume','a piece of land for sale','lovely 表示令人愉快或美好的。'),Q('Where did they spend the afternoon?','by the lake','inside a lorry engine','at a lottery drawing in a tunnel','语境说他们在湖边度过下午。'),Q('Which adjective is close in meaning to lovely here?','delightful','loutish','lost','delightful 可形容令人愉快的下午。'),Q('Lovely is most likely to modify?','a person, place, or experience','a past-tense verb only','a unit of measurement only','lovely 是形容人、地方或经历的形容词。')]);
P('lover','Lover comes from love plus -er and can mean a person with deep affection for someone or a person who is enthusiastic about a subject.',[C('lover.s1','兴趣群体','A lover of classical music, Mei travels to hear small orchestras perform works by unfamiliar composers.','梅是古典音乐爱好者，她会去听小型乐团演奏不熟悉作曲家的作品。','A lover of classical music / Mei travels / to hear small orchestras / perform works by unfamiliar composers.','lover of something 指热爱某事物的人。','她持续寻找古典音乐演出，体现浓厚爱好。'),C('lover.s1','关系描写','The novel portrays him as her lover, the person with whom she has a romantic relationship.','小说把他描写成她的恋人，也就是与她有恋爱关系的人。','The novel portrays him / as her lover / the person / with whom she has a romantic relationship.','lover 也可指有恋爱或性关系的人，语境可能较私密。','句子明确定义两人存在恋爱关系。')],M('The article called him a lover of classical music although he disliked every concert and never listened to it.','The article called him a lover of classical music because he regularly sought out performances.','从不听且讨厌音乐不支持“爱好者”之义。'),[Q('A lover of classical music is?','someone who enjoys it deeply','someone who sells only loudspeakers','someone who has never heard music','lover of 表示热爱某个领域的人。'),Q('In the novel, her lover is?','the person in a romantic relationship with her','her music teacher with no relationship','a ticket drawn in a lottery','lover 也可指恋人。'),Q('Which construction means an enthusiast?','a lover of art','a love of driving the lorry','a lovely of art','lover of art 指艺术爱好者。'),Q('The suffix -er in lover forms a word for?','a person connected with loving','a place to store lost objects','the quality of being loud','love 加 -er 构成人称名词。','word-formation')]);
P('loving','Loving is formed from love plus -ing and describes behaviour that shows affection, warmth, and care.',C('loving.s1','家庭照护','Her loving care for the injured bird included fresh water, quiet shelter, and a call to a wildlife centre.','她悉心照料受伤的小鸟，为它准备干净的水和安静的庇护所，还联系了野生动物中心。','Her loving care / for the injured bird / included fresh water / quiet shelter, and a call to a wildlife centre.','loving 作形容词修饰 care；for 引出受到关爱的对象。','细致照料体现关爱而非仅仅照看。'),M('The note described his loving care although he ignored the injured bird and left it without water.','The note described his loving care because he protected the bird and arranged expert help.','忽视受伤动物与关爱不符。'),[Q('Loving care is care that shows?','affection and concern','high volume','a low price','loving 表示充满爱与关怀。'),Q('What did she provide for the bird?','water and quiet shelter','a lottery ticket and a lorry','a loudspeaker and a jacket','例句列出水、庇护所和求助措施。'),Q('Which phrase is natural?','a loving parent','a loving loudly','a loveingly parent','loving 可作形容词修饰 parent。','grammar'),Q('What makes the care loving in the example?','she protected the bird and sought expert help','she left it alone without water','she used a bright orange coat','保护和求助体现关怀。')]);
P('low','Low comes from Old Norse lágr (“low”); it describes little height, amount, volume, mood, or a minimum point depending on context.',[C('low.s1','家具高度','The low shelf was easy for the children to reach without climbing or asking an adult for help.','孩子们不用攀爬或请大人帮忙，就能轻松够到那张矮架子。','The low shelf / was easy for the children to reach / without climbing / or asking an adult for help.','low 修饰 shelf，指高度不高；easy to reach 说明实际影响。','架子离地较近，符合高度义 s1。'),C('low.s2','库存数量','The shop kept prices low during the opening week to attract first-time customers.','商店在开业首周保持低价，以吸引首次光顾的顾客。','The shop kept prices low / during the opening week / to attract first-time customers.','keep something low 表示使数值或程度保持较低。','价格不高，符合数量或价值义 s2。'),C('low.s3','情绪状态','After the project was cancelled, Ravi felt low for a few days but gradually regained his energy.','项目取消后，拉维低落了几天，但逐渐恢复了精力。','After the project was cancelled / Ravi felt low / for a few days / but gradually regained his energy.','feel low 是描述情绪低落的表语结构。','项目取消后精神不振，符合心理义 s3。'),C('low.s4','说话音量','She spoke in a low voice in the library so the other readers could concentrate.','她在图书馆里低声说话，以免打扰其他读者。','She spoke / in a low voice / in the library / so the other readers could concentrate.','a low voice 指音量小；注意 low 在这里修饰 voice。','图书馆里轻声交谈符合低音量义 s4。')],M('The shelf was low, standing several metres above the floor where no child could reach it.','The shelf was low, close to the floor and easy for children to reach.','数米高、无法够到的架子并不矮。'),[Q('The low shelf was easy for children to?','reach','hear from a distant platform','use as a lottery ticket','low 描述架子高度较低。'),Q('Keeping prices low means?','making them relatively inexpensive','raising them above every competitor','removing all price labels','此处 low 指价格水平较低。'),Q('Ravi felt low after the cancellation means he felt?','unhappy and without much energy','physically tall','loud and noisy','feel low 可描述情绪低落。'),Q('A low voice is?','quiet in volume','high in pitch and extremely loud','a road vehicle','low 可描述说话音量较小。')]);
P('low-risk','Low-risk combines low and risk and describes an option unlikely to cause serious harm or loss.',C('low-risk.s1','安全决策','The clinic offered a low-risk procedure after explaining that serious complications were unlikely but not impossible.','诊所解释严重并发症的可能性较低但并非不存在后，提供了一项低风险手术。','The clinic offered a low-risk procedure / after explaining / that serious complications were unlikely / but not impossible.','low-risk 作复合形容词，放在名词 procedure 前修饰风险程度。','严重并发症不太可能发生，符合低风险定义。'),M('The procedure was called low-risk even though doctors expected severe complications in most patients.','The procedure was called low-risk because severe complications were considered unlikely.','预计多数患者会有严重并发症，不应称为低风险。'),[Q('A low-risk procedure is one that?','is unlikely to cause serious harm','is guaranteed to cause injury','has no medical purpose','low-risk 表示严重危险发生的可能性较低。'),Q('Does low-risk mean that complications are impossible?','No, they are unlikely but still possible.','Yes, risk means zero in every case.','Only if the procedure is free.','低风险不等于绝无风险。'),Q('Which hyphenation matches the assigned headword?','low-risk','lowrisk','risk-low','复合形容词按词条拼作 low-risk。','spelling'),Q('Which choice is low-risk in the example?','the clinic procedure described','an activity expected to injure most people','a guaranteed financial loss','例句里的治疗并发症严重风险低。')]);
P('lowa','Lowa is a distinct geographic name in the source entry and must not be silently respelled as Iowa, the US state.',[C('lowa.s1','地图校读','The surveyor copied “Lowa” exactly from the local map and checked the original before treating it as a place-name.','测绘员把地图上的“Lowa”原样抄下，并在将其作为地名处理前核对了原件。','The surveyor copied “Lowa” exactly / from the local map / and checked the original / before treating it as a place-name.','Lowa 作为词条中的专名保留首字母大写，不能擅自改成 Iowa。','语境明确根据地图原样抄录地名拼写，符合该条目的地名义。'),C('lowa.s2','户外装备','The shop’s LOWA display featured hiking boots beside its trail shoes and waterproof packs.','商店的 LOWA 展区在登山鞋旁陈列了徒步鞋和防水背包。','The shop’s LOWA display / featured hiking boots / beside its trail shoes / and waterproof packs.','品牌用法通常全大写 LOWA，指户外鞋履品牌。','登山装备展台里的品牌名对应 s2。')],M('The cartographer changed Lowa to Iowa without checking the source map, although the assigned name was spelled Lowa.','The cartographer retained Lowa as printed on the source map and checked it before editing.','清单要求保留 Lowa 原拼写，不能擅自把它规范成 Iowa。','spelling'),[Q('How should the map name in the example be copied?','exactly as “Lowa”','always corrected to “Iowa”','translated into “low land”','例句强调按来源保留 Lowa 拼写。'),Q('In the shop display, LOWA refers to?','an outdoor footwear brand','the US state of Iowa','a type of skin lotion','品牌义指户外鞋履品牌。'),Q('Why did the surveyor check the original map?','to verify the uncommon place-name spelling','to calculate a lottery prize','to measure a loudspeaker','来源核对有助于保留地名的准确拼写。'),Q('Which spelling is the distinct assigned word?','Lowa','Iowa','low-risk','A65 清单指定的是 Lowa，不是 Iowa。','spelling')]);
P('lower','Lower is the comparative form of low and also a verb meaning to move or bring something down.',[C('lower.s1','舞台设置','The stage crew lowered the screen slowly so it would stop just above the first row of seats.','舞台工作人员慢慢降下屏幕，让它停在第一排座位的上方。','The stage crew lowered the screen / slowly / so it would stop / just above the first row.','lower 作及物动词，lower something 表示把某物降下来。','屏幕从高处被移到较低位置，符合动词义。')],M('The crew lowered the screen by lifting it higher above the stage.','The crew lowered the screen by bringing it down toward the stage.','向上抬高是 raise，不是 lower。','confusable'),[Q('What did the crew lower?','the screen','the first row of seats','the stage curtain colour','lower 作动词时表示把屏幕降下来。'),Q('If one shelf is lower than another, it is?','closer to the ground','farther above the ceiling','louder in sound','lower 是 low 的比较级。','grammar'),Q('Which verb is the opposite of lower?','raise','lounge','lose','raise 表示向上抬，与 lower 相反。','confusable'),Q('Why did the crew lower the screen slowly?','to stop it just above the first row','to make it fly above the ceiling','to turn it into a seat','慢慢放下有助于让屏幕停在指定高度。')]);
P('lowest','Lowest is the superlative form of low, identifying the smallest height, amount, degree, or position in a group.',C('lowest.s1','能源账单','The household used the least electricity in April, making that month’s bill the lowest of the year.','这户人家四月份用电最少，因此当月电费是全年最低的。','The household used the least electricity in April / making that month’s bill / the lowest of the year.','lowest 是 low 的最高级；the lowest 与 of the year 表示一组中的最低值。','四月账单低于全年其他月份。'),M('April had the lowest bill even though every other month’s bill was smaller.','April had the lowest bill because it was smaller than the bills for the other months.','其他月份账单都更低，就不能称四月最低。'),[Q('The lowest bill of the year is?','smaller than every other monthly bill','the largest bill in the household','the first bill ever printed','lowest 表示一组里数值最小的。'),Q('Lowest is the superlative of?','low','lower','loud','low–lower–lowest 是比较级和最高级形式。','grammar'),Q('What caused the April bill to be lowest?','the household used the least electricity','the family bought a lorry','the screen was lowered','四月用电最少，因此账单最低。'),Q('Which phrase is correct?','the lowest price','the lowerest price','the low price than all','形容词最高级形式是 the lowest。','grammar')]);
P('lowland','Lowland combines low and land and can mean low flat terrain, Scotland’s Lowlands, or something living in such terrain.',[C('lowland.s1','地形勘察','The road crossed a broad lowland where seasonal floods spread across the flat fields.','这条路穿过一片宽阔的低地，季节性洪水会漫过平坦田野。','The road crossed / a broad lowland / where seasonal floods spread / across the flat fields.','lowland 作可数名词，指海拔较低、地势平坦的土地。','低洼平坦地形易受洪水影响，符合 s1。'),C('lowland.s2','苏格兰地理','The railway connected the Scottish Lowlands with the Highlands through a route used by commuters and visitors.','这条铁路通过一条通勤者和游客使用的线路连接了苏格兰低地与高地。','The railway connected / the Scottish Lowlands / with the Highlands / through a route used by commuters and visitors.','专指苏格兰南部地区时常大写 Lowlands，并与 Highlands 对举。','与苏格兰高地相对的 Lowlands 符合 s2。'),C('lowland.s3','生态分类','Several lowland plants thrive in the warm, damp soil beside the slow-moving river.','几种低地植物在缓流河边温暖潮湿的土壤中生长旺盛。','Several lowland plants thrive / in the warm, damp soil / beside the slow-moving river.','lowland 作前置定语，描述生长于低地的物种。','植物适生于低地环境，符合 s3。')],M('The botanist called it a lowland species even though it grows only on exposed high mountain peaks.','The botanist called it a lowland species because it thrives on warm, flat terrain near the river.','只生长在高山峰顶的物种不属于低地物种。'),[Q('A lowland is usually?','low, relatively flat terrain','a high mountain summit','a loud indoor room','lowland 指低洼、相对平坦的土地。'),Q('The Scottish Lowlands are contrasted with?','the Highlands','the lost-and-found','the loudest streets','苏格兰地理中的 Lowlands 与 Highlands 相对。'),Q('Lowland plants in the example thrive beside?','a slow-moving river','a dry summit above the clouds','an airport loudspeaker','例句说明植物生长在河边低地土壤。'),Q('Which form uses lowland as an adjective?','lowland plants','a lot of land','the lowerest ground','lowland 可放在 plants 前作定语。')]);
P('lowly','Lowly comes from low plus -ly and describes a humble rank or position, often one with little status.',C('lowly.s1','职业经历','She began in a lowly filing job but eventually became director after years of careful work.','她从一个不起眼的档案整理岗位做起，多年认真工作后最终成为主管。','She began / in a lowly filing job / but eventually became director / after years of careful work.','lowly 作形容词修饰 job，强调职位地位较低。','初级档案岗位与后来晋升的主管地位形成对照。'),M('The company described the chief executive’s lowly position even though she had final authority over every department.','The company described the junior assistant’s lowly position because she had little status or authority.','拥有全公司最终决策权不属于低微职位。'),[Q('A lowly job usually has?','little status or rank','the highest authority','the loudest sound','lowly 指社会或职业地位低微。'),Q('What was the woman’s first job?','filing work','company director','lottery judge','她从档案整理岗位开始。'),Q('Which word is closest in meaning to lowly?','humble','lucrative','loutish','humble 可表示地位低微或不显赫。'),Q('The suffix -ly in lowly forms an?','adjective describing rank','adverb meaning loudly','irregular plural','low 加 -ly 构成形容词。','word-formation')]);
P('loyal','Loyal came through Old French leial from Latin legalis (“of the law”); it means faithful to a person, group, country, or duty.',[C('loyal.s1','友谊','Even after moving abroad, Sam stayed loyal to the friends who had supported him through school.','即使搬到国外，山姆仍忠于那些在求学时期支持过他的朋友。','Even after moving abroad / Sam stayed loyal / to the friends / who had supported him through school.','loyal 常与 to 连用，说明忠诚或支持的对象。','长期支持朋友符合人际忠诚义 s1。'),C('loyal.s2','公共服务','The officer remained loyal to her oath and refused to misuse the authority of her position.','这名官员忠于自己的誓言，拒绝滥用职位赋予的权力。','The officer remained loyal / to her oath / and refused to misuse / the authority of her position.','loyal to a duty/oath 表示忠于职责或原则。','遵守誓言体现对职责的忠贞。')],M('The soldier was loyal to the mission, so he deliberately abandoned it as soon as it became difficult.','The soldier was loyal to the mission and continued to support it when conditions became difficult.','困难时故意抛弃使命与忠诚相悖。'),[Q('Sam stayed loyal to his friends means he?','continued to support them','forgot their names on purpose','sold their house','loyal to people 表示持续支持、忠心。'),Q('The officer was loyal to her oath by?','refusing to misuse her authority','breaking the promise for personal gain','leaving the oath unsigned','她遵守誓言并拒绝滥权。'),Q('Which preposition commonly follows loyal?','to','at','throughout','常见结构为 loyal to someone or something。','collocation'),Q('A loyal supporter is likely to?','remain faithful through difficulties','change sides whenever convenient','avoid every commitment','忠诚意味着持续支持而非随意变节。')]);
P('loyalist','Loyalist is formed from loyal plus -ist and names someone who supports an existing authority or established political order.',C('loyalist.s1','政治历史','During the rebellion, the loyalists continued to support the crown while other groups demanded independence.','叛乱期间，忠诚派继续支持王室，而其他团体要求独立。','During the rebellion / the loyalists continued to support the crown / while other groups / demanded independence.','loyalist 作可数名词，常以 -ist 指持某种政治立场的人。','支持现有王权、反对独立运动符合 s1。'),M('The article called her a loyalist even though she campaigned to overthrow the authority she supposedly supported.','The article called her a loyalist because she defended the existing authority against the rebellion.','积极推翻所支持的当局与 loyalist 身份矛盾。'),[Q('A loyalist in the example supported?','the crown and existing authority','the campaign to end the monarchy','a nearby lowland farm','loyalist 支持当时的王室与既有权威。'),Q('Which group is likely to be called loyalists?','people defending the current government against a rebellion','people seeking to overthrow that government','tourists visiting a museum','忠诚派站在维护当局的一方。'),Q('Which suffix identifies a person holding a position?','-ist','-ness','-ly','-ist 常构成人称名词或立场名词。','word-formation'),Q('What is the contrast described in the sentence?','loyalists supported the crown; others demanded independence','everyone agreed to abolish the crown','the crown supported every rebel','句子对比支持王室和要求独立的团体。')]);
P('loyally','Loyally is formed from loyal plus -ly and means with faithful, steady support for someone or something.',C('loyally.s1','团队协作','For ten years, Mara loyally served the community centre, even when funding cuts made the work difficult.','十年来，玛拉一直忠心服务社区中心，即使削减经费让工作变得艰难也没有离开。','For ten years / Mara loyally served the community centre / even when funding cuts / made the work difficult.','loyally 是副词，修饰 served，表示持续忠实地服务。','经年服务且面对困难仍支持，体现忠诚。'),M('He loyally supported the group by abandoning it whenever it needed help.','He loyally supported the group by remaining with it and helping during difficult periods.','需要帮助时离开组织不是忠实支持。'),[Q('Mara loyally served the centre means she?','supported it faithfully over time','visited it once by accident','sold it to a rival group','loyally 表示忠实地、持续地支持。'),Q('What made her service notable?','she continued despite funding cuts','she left before the work began','she never helped anyone','困难时仍服务体现忠诚。'),Q('Loyally is an adverb modifying?','served','community','funding','loyally 修饰动词 served。','grammar'),Q('Which phrase is natural?','loyally support a team','loyalty support a team','loyally supporter a team','副词 loyally 可修饰动词 support。','grammar')]);
P('loyalty','Loyalty came through Old French from loyal and names faithful commitment to a person, group, or principle.',C('loyalty.s1','顾客关系','The café earned customer loyalty by remembering regulars’ names and fixing mistakes without making excuses.','这家咖啡馆通过记住常客的名字、并且不找借口地改正错误，赢得了顾客的忠诚。','The café earned customer loyalty / by remembering regulars’ names / and fixing mistakes / without making excuses.','loyalty 作不可数名词，customer loyalty 指顾客持续选择该商家。','顾客愿意持续支持，体现忠诚。'),M('The café had strong customer loyalty even though every regular stopped visiting and recommended its competitors.','The café had strong customer loyalty because regulars continued to return and recommend it.','常客都离开并推荐竞争对手，不体现顾客忠诚。'),[Q('Customer loyalty means customers?','continue to support a business','never return after one visit','own the café’s building','loyalty 指持续支持和忠心。'),Q('How did the café encourage loyalty?','it remembered regulars and corrected mistakes','it ignored every complaint','it changed its name daily','周到服务和改错有助于赢得顾客支持。'),Q('Which word is the noun for being loyal?','loyalty','loyally','loyalist','loyalty 是名词。','word-formation'),Q('Which phrase is natural?','loyalty to a principle','loyalty in a principle only','loyalty with being loudly','常用结构是 loyalty to someone or something。','collocation')]);
P('lubricant','Lubricant is formed from lubricate and names a substance that reduces friction between surfaces that move against each other.',C('lubricant.s1','设备维护','The technician applied a food-safe lubricant to the conveyor bearings so the rollers would move smoothly.','技师在传送带轴承上涂了食品级润滑剂，让滚轮运转顺畅。','The technician applied / a food-safe lubricant / to the conveyor bearings / so the rollers would move smoothly.','lubricant 作可数或不可数名词；apply a lubricant to a moving part。','物质减少轴承摩擦，符合 s1。'),M('The mechanic chose a lubricant that increased friction and made the conveyor bearings seize.','The mechanic chose a lubricant that reduced friction so the bearings could turn smoothly.','使摩擦增加并卡住轴承的物质不是润滑剂。'),[Q('A lubricant is used to?','reduce friction between moving surfaces','make a surface louder','increase the weight of a machine','润滑剂减少运动部件间的摩擦。'),Q('Where did the technician apply it?','to the conveyor bearings','to the lost-and-found notice','to a lottery ticket','语境说润滑剂涂在传送带轴承上。'),Q('What result did the lubricant help achieve?','the rollers moved smoothly','the bearings became immovable','the conveyor changed colour','降低摩擦让滚轮运转顺畅。'),Q('Which phrase is natural?','apply lubricant to a bearing','apply lubricant at a person','lubricant the bearing down','常见结构是 apply lubricant to a part。','collocation')]);
P('lubricate','Lubricate comes from Latin lubricare (“make slippery”) and means to apply oil or grease, or figuratively to make a process smoother.',[C('lubricate.s1','自行车保养','Before the long ride, I lubricated the bicycle chain and wiped away the excess oil with a clean cloth.','长途骑行前，我给自行车链条上了润滑油，并用干净的布擦掉多余油渍。','Before the long ride / I lubricated the bicycle chain / and wiped away / the excess oil.','lubricate 作及物动词，lubricate a chain 表示给链条加润滑剂。','链条上油以减少摩擦，符合 s1。'),C('lubricate.s2','谈判流程','A neutral facilitator helped lubricate the negotiations by making sure each side could respond without interruption.','一位中立协调人通过确保双方都能不受打断地回应，帮助谈判顺利进行。','A neutral facilitator helped lubricate the negotiations / by making sure / each side could respond / without interruption.','比喻用法中 lubricate 可接 process/negotiations，意为使进程更顺畅。','协调降低沟通阻碍，使谈判更顺利。')],M('He lubricated the bicycle chain by washing away all oil and leaving the metal parts dry and squeaky.','He lubricated the bicycle chain by applying oil so its links could move with less friction.','去掉润滑油会增加摩擦，不是给链条润滑。'),[Q('What did the rider lubricate?','the bicycle chain','the clean cloth','the road surface','lubricate the chain 表示给链条上油。'),Q('How can someone lubricate negotiations figuratively?','help each side communicate smoothly','interrupt every speaker repeatedly','remove all chances to respond','比喻义是让谈判过程更顺畅。'),Q('Which substance commonly lubricates a chain?','oil','sand','chalk dust','油能减少链节间摩擦。'),Q('Which pair shows the literal and figurative uses?','oil a chain; smooth a negotiation','lower a screen; count a ticket','lose a map; love a song','lubricate 可指实体润滑，也可比喻促进流程。')]);
P('lubrication','Lubrication is the process of applying a substance to reduce friction and wear between moving parts.',C('lubrication.s1','机械工程','Regular lubrication of the pump bearings prevented overheating during the factory’s overnight shift.','定期给泵轴承润滑，防止它们在工厂夜班期间过热。','Regular lubrication / of the pump bearings / prevented overheating / during the factory’s overnight shift.','lubrication 作不可数过程名词，of 引出被润滑部件。','减少轴承摩擦可避免过热与磨损。'),M('The machine failed because lubrication had deliberately increased friction between every moving part.','The machine ran smoothly because lubrication reduced friction between its moving parts.','润滑作用是减小摩擦，而非有意增加摩擦。'),[Q('Lubrication is the process of?','reducing friction between moving parts','raising a machine’s volume','painting every part bright orange','lubrication 指减少运动部件摩擦的过程。'),Q('What did regular lubrication prevent?','overheating of the pump bearings','the factory opening on time','the pump becoming a loudspeaker','润滑避免轴承在运转中发热。'),Q('Which noun is the process related to lubricate?','lubrication','lubricity','loutishness','lubrication 表示润滑过程。','word-formation'),Q('Why do machines need lubrication?','to limit friction and wear','to increase resistance deliberately','to make moving parts impossible to turn','润滑可减少摩擦和磨损。')]);
P('lubricity','Lubricity comes from Latin lubricitas and means physical slipperiness; in literary use it can also suggest lewd or slippery behaviour.',[C('lubricity.s1','材料测试','The oil’s lubricity was tested by measuring how easily the coated metal surfaces slid past each other.','研究人员通过测量涂油金属表面相互滑动的难易程度来测试油的润滑性。','The oil’s lubricity was tested / by measuring / how easily the coated metal surfaces / slid past each other.','lubricity 作技术名词，指材料减少摩擦、保持滑动的性质。','涂层使金属表面滑动更容易，符合 s1。'),C('lubricity.s2','文学评论','The critic objected to the character’s lubricity, describing his evasive, sexually suggestive remarks as indecent.','评论家批评该人物言谈圆滑放荡，认为他闪烁其词、带有性暗示的话语很不雅。','The critic objected / to the character’s lubricity / describing his evasive, sexually suggestive remarks / as indecent.','文学义 lubricity 可指油滑或淫荡言行，语体较旧且带贬义。','评论明确提到闪烁其词且淫猥的言谈，符合 s2。')],M('The test showed high lubricity because the dry surfaces gripped each other tightly and resisted all sliding.','The test showed high lubricity because the coated surfaces slid easily with little friction.','紧紧咬合、难以滑动表示润滑性差。'),[Q('In the materials test, lubricity means?','the ability to slide with little friction','the loudness of a machine','the loyalty of a technician','技术义指滑动顺畅、摩擦小的性质。'),Q('What did the critic object to?','evasive and indecently suggestive remarks','a clear engineering diagram','a loyal community service','该语境中的文学义涉及油滑或淫猥言谈。'),Q('Which surface suggests high lubricity?','one that slides smoothly when coated','one that locks together and cannot move','one covered in dry sand','润滑性高的表面更容易滑动。'),Q('The literary sense of lubricity is?','a figurative negative sense','a measurement of sound','a type of vehicle','该词另有贬义的文学用法。')]);
P('luce','Luce is an old English fish name for a large pike (Esox lucius), especially in historical or literary writing.',C('luce.s1','历史渔业','The medieval inventory listed one large luce among the fish delivered to the manor kitchen that morning.','中世纪清单把一条大狗鱼列在当天早晨送往庄园厨房的鱼货中。','The medieval inventory listed / one large luce / among the fish / delivered to the manor kitchen.','luce 作可数名词，是历史用语，指较大的狗鱼。','庄园清单所列的大型淡水鱼符合该旧称。'),M('The naturalist identified the luce as a small flowering plant growing in the pond.','The naturalist identified the luce as a large pike caught in the river.','luce 指狗鱼，不是池塘开花植物。'),[Q('A luce is an old name for a?','large pike','lowland flower','skin lotion','luce 是大型狗鱼的旧称。'),Q('Where was the luce recorded in the example?','in a medieval fish inventory','on a modern lottery ticket','inside a loudspeaker','例句说它列在中世纪送往厨房的鱼货清单里。'),Q('What kind of animal is a luce?','a fish','a bird','a flowering tree','luce 指鱼类。'),Q('Which context best suits the word luce?','historical writing about a large pike','a current weather forecast','a recipe for hand lotion','该词是狗鱼的旧称，适合历史或文学语境。')]);
P('lucent','Lucent comes from Latin lucentem, from lucere (“shine”); it describes something softly glowing or clear enough for light to pass through.',C('lucent.s1','文学景象','A lucent moon showed through the thin clouds, casting a pale glow on the quiet harbour.','一轮清辉的月亮透过薄云，在安静的港口投下淡淡光芒。','A lucent moon showed / through the thin clouds / casting a pale glow / on the quiet harbour.','lucent 作文学色彩较浓的形容词，修饰发光或透光的事物。','月光柔和地透过薄云，符合 s1。'),M('The glass was described as lucent although it was opaque and allowed no light through.','The glass was described as lucent because light passed softly through it.','不透光的材料不能称为 lucent。'),[Q('A lucent moon is?','softly glowing','completely silent','very low in price','lucent 表示发光或清透。'),Q('What did the moonlight do?','cast a pale glow on the harbour','lower the water level','draw a lottery ticket','月光照亮了安静的港口。'),Q('Which material can be lucent?','thin glass that lets light through','opaque stone that blocks all light','a soundproof metal box','能透光的材料符合 lucent 的透明义。'),Q('Lucent is closest in meaning to?','luminous or translucent','loutish','lucrative','lucent 可表示发光或透光。')]);
P('lucid','Lucid comes from Latin lucidus (“shining, clear”) and means clearly expressed or easy to understand.',C('lucid.s1','科普写作','The guide gave a lucid explanation of the eclipse, using a simple diagram to show why the shadow crossed the Moon.','导览员对日食作了清晰的解释，并用一张简单图示说明影子为何会掠过月球。','The guide gave / a lucid explanation of the eclipse / using a simple diagram / to show why the shadow crossed the Moon.','lucid 作形容词修饰 explanation，描述表达清楚易懂。','图示和清楚说明让复杂现象易于理解。'),M('The lecturer’s lucid explanation was impossible to follow because it was confused and lacked any clear connection.','The lecturer’s lucid explanation was easy to follow because each step was stated clearly.','难以理解、混乱的说明不能称为 lucid。'),[Q('A lucid explanation is?','clear and easy to understand','full of unexplained contradictions','bright orange in colour','lucid 指表达清晰、容易理解。'),Q('What helped explain the eclipse?','a simple diagram','a lost wallet','a low-risk ticket','图示帮助说明影子经过月球的原因。'),Q('Which word is closest in meaning to lucid?','clear','loutish','lopsided','clear 可形容容易理解的说明。'),Q('Which phrase is natural?','a lucid argument','lucidly argument','a lucidity argument','lucid 作形容词修饰 argument。','grammar')]);
P('luck','Luck has an uncertain deeper origin in English; it names chance that brings success or failure and sometimes the good result itself.',[C('luck.s1','赛事结果','It was pure luck that the ball bounced back into play instead of landing out of bounds.','球没有出界而是弹回场内，纯属运气。','It was pure luck / that the ball bounced back into play / instead of landing / out of bounds.','luck 作不可数名词，pure luck 强调结果由偶然造成。','不可预测的弹跳结果体现机遇。'),C('luck.s2','好运消息','By sheer luck, the lost keys were found in the last box the volunteers searched.','纯属走运，志愿者在最后一个箱子里找到了丢失的钥匙。','By sheer luck / the lost keys were found / in the last box / the volunteers searched.','luck 也可指偶然带来的有利结果，常见 by luck/by sheer luck。','钥匙恰好在最后一个箱子里出现，是好运结果。')],M('The team said it was luck that the ball went out every time, even though the bounce was carefully controlled and predictable.','The team called it luck when an unpredictable bounce sent the ball back into play.','受控且可预测的结果不属于偶然运气。'),[Q('“Pure luck” means the result came from?','chance rather than a planned action','a strict written rule','a lowland river','pure luck 强调偶然性。'),Q('The keys were found in the last box by sheer luck means?','a fortunate chance led to their discovery','the volunteers knew exactly where they were','the keys were never missing','by sheer luck 表示纯属碰巧的好结果。'),Q('Which phrase is idiomatic?','good luck with the exam','luck of the loudspeaker volume','a lucks of keys','good luck 是常见表达。','collocation'),Q('Can luck bring a bad result too?','Yes, chance can bring success or failure.','No, luck only means a guaranteed win.','Only when a person owns a lorry.','luck 指可能带来成功或失败的偶然因素。')]);
P('luckily','Luckily is formed from lucky plus -ly and is an adverb used to introduce a favourable result that happened by chance.',C('luckily.s1','出行意外','Luckily, the bus driver noticed the forgotten backpack before the vehicle left the station.','幸好，公交车离站前司机发现了被遗忘的背包。','Luckily / the bus driver noticed the forgotten backpack / before the vehicle / left the station.','luckily 常置于句首，用逗号隔开，评注后面发生的有利情况。','背包及时被发现，避免了遗失，属于幸运结果。'),M('Luckily, nobody saw the warning sign, so everyone walked into the dangerous area unnoticed.','Luckily, the driver saw the warning sign and stopped the passengers before they entered the dangerous area.','无人看见警示而进入危险区是坏结果，不应由 luckily 引出。'),[Q('Luckily introduces?','a favourable result that happened by chance','a planned list of instructions','a certain failure with no good outcome','luckily 表示碰巧出现了有利结果。'),Q('What was noticed before departure?','the forgotten backpack','a lost-and-found office','a lowland map','司机及时发现了背包。'),Q('Where does luckily often appear in this sentence pattern?','at the beginning, followed by a comma','inside the spelling of backpack','only after a plural noun','句首副词 luckily 后常接逗号。','punctuation'),Q('Luckily is related to which adjective?','lucky','loud','lucent','luckily 由 lucky 加 -ly 构成。','word-formation')]);
P('lucky','Lucky is formed from luck plus -y and describes favourable chance or something believed to bring good fortune.',[C('lucky.s1','比赛意外','We were lucky that the rain stopped just before the outdoor final began.','户外决赛开始前雨恰好停了，我们很幸运。','We were lucky / that the rain stopped / just before the outdoor final / began.','lucky 作表语形容词，后接 that 从句说明幸运的事情。','比赛前雨停是有利的偶然结果，符合 s1。'),C('lucky.s2','民间信念','In her family, the old coin was considered a lucky charm and was carried on every important journey.','在她家里，这枚旧硬币被视为吉祥物，每次重要旅行都会随身携带。','In her family / the old coin was considered / a lucky charm / and was carried on every important journey.','lucky 可修饰被认为能带来好运的物品。','硬币被认为具有带来好运的作用，符合 s2。')],M('They called the coin lucky even though they believed it brought bad fortune and carried it only as a warning.','They called the coin lucky because they believed it brought good fortune.','被认为带来厄运的硬币不是 lucky charm。'),[Q('We were lucky the rain stopped means?','a favourable event happened by chance','the team controlled every cloud','the match was cancelled for certain','lucky 表示碰巧遇到有利结果。'),Q('A lucky charm is believed to?','bring good fortune','make a person speak loudly','reduce friction in a machine','吉祥物被认为能带来好运。'),Q('Which situation best fits lucky?','finding a lost key just before leaving','missing a train after arriving early','breaking a new tool deliberately','临走前找到钥匙是幸运的结果。'),Q('Which word can mean “believed to bring good fortune”?','lucky','loutish','lowly','lucky 也可形容被认为吉利的物品。')]);
P('lucrative','Lucrative comes from Latin lucrativus, from lucrum (“profit”); it describes work, business, or a deal that produces substantial profit or pay.',[C('lucrative.s1','商业经营','The repair contract proved lucrative because the company earned a large profit after covering its labour and equipment costs.','这份维修合同利润丰厚，因为公司支付人工和设备成本后仍赚了很多。','The repair contract proved lucrative / because the company earned a large profit / after covering / its labour and equipment costs.','lucrative 作表语形容词，常描述 business, contract, deal 等带来利润的事物。','扣除成本后仍有高额利润，符合 s1。'),C('lucrative.s2','职业报酬','The consultant left a secure post for a more lucrative position that offered a much higher salary.','这名顾问离开稳定职位，转去一个薪水高得多、报酬更丰厚的岗位。','The consultant left a secure post / for a more lucrative position / that offered / a much higher salary.','lucrative 可描述收入高、报酬丰厚的职位。','新职位薪水大幅提高，符合 s2。')],M('The contract was lucrative even though it paid less than the cost of materials and produced no profit.','The contract was lucrative because its income greatly exceeded the costs.','收入低于成本且没有利润不叫 lucrative。'),[Q('A lucrative contract brings?','substantial profit','a guaranteed financial loss','a loud announcement','lucrative 表示能带来丰厚利润。'),Q('A lucrative position may offer?','a much higher salary','no pay at all','a lowland map','报酬高的职位也可称 lucrative。'),Q('Which item can be lucrative?','a profitable business deal','a broken loudspeaker with no buyer','a missing key','lucrative 常修饰有利可图的交易。'),Q('The word lucrative is connected historically with?','profit','loyalty','low height','lucrative 源自表示利润的钱财词根 lucrum。')]);
P('lucre','Lucre comes from Latin lucrum (“gain, profit”) and means money or financial gain, often with disapproval in phrases such as filthy lucre.',C('lucre.s1','商业讽刺','The novelist mocked the official’s greed for lucre, showing him accepting bribes while claiming to serve the public.','小说家讽刺这名官员贪图钱财，描写他一边声称服务公众、一边收受贿赂。','The novelist mocked / the official’s greed for lucre / showing him accepting bribes / while claiming to serve the public.','lucre 是较正式或文学化的贬义名词，常指贪图的钱财。','贿赂与贪财体现带贬义的钱财义。'),M('The story praised his love of lucre because he refused every bribe and gave all his money away.','The story criticized his love of lucre because he accepted bribes for personal gain.','拒绝贿赂且捐出所有钱财不体现贪图钱财。'),[Q('Lucre is?','money or financial gain, often viewed disapprovingly','a type of fish','a low-volume voice','lucre 指钱财，常含贪财的贬义。'),Q('What did the official accept?','bribes','a lost pet','a low-risk medical procedure','收受贿赂体现贪图钱财。'),Q('Which phrase is a familiar expression?','filthy lucre','lucid lucre of the moon','a lorry of lucre','filthy lucre 是带贬义的固定表达。','collocation'),Q('Lucre comes from a Latin word meaning?','gain or profit','low land','clear light','lucrum 表示所得或利润。')]);
P('ludicrous','Ludicrous comes from Latin ludicrus (“playful, fit for sport”) and now describes something so absurd or silly it cannot be taken seriously.',C('ludicrous.s1','预算评议','The council rejected the ludicrous proposal to build a glass roof over the entire outdoor football field.','市政委员会否决了给整座露天足球场盖玻璃屋顶这一荒唐提议。','The council rejected / the ludicrous proposal / to build a glass roof / over the entire outdoor football field.','ludicrous 作形容词修饰 proposal，说明计划荒谬得难以认真对待。','露天球场盖全玻璃屋顶的设想极不合理。'),M('The committee called the plan ludicrous because it was practical, affordable, and had already succeeded elsewhere.','The committee called the plan ludicrous because it was absurdly impractical and far too costly.','切实可行且已成功的方案不符合荒谬义。'),[Q('A ludicrous proposal is?','absurd and hard to take seriously','carefully tested and practical','very low in physical height','ludicrous 表示荒谬可笑。'),Q('What did the council reject?','a glass roof over an outdoor football field','a new lost-and-found desk','a low-risk clinic procedure','例句中被否决的是给露天足球场加屋顶。'),Q('Which adjective is closest in meaning to ludicrous?','ridiculous','lucent','loyal','ridiculous 同样表示荒谬。'),Q('Which situation is ludicrous?','a proposal that is absurdly impractical','a proven plan that fits the budget','a simple repair with clear instructions','不切实际又荒唐的方案符合 ludicrous。')]);
P('lug','Lug has an uncertain origin; as a verb it means to drag or carry something heavy awkwardly, and as a noun it can name a projecting handle or fitting.',[C('lug.s1','搬运设备','We had to lug the heavy generator up two flights of stairs because the service lift was broken.','由于货梯坏了，我们只好把沉重的发电机吃力地拖上两层楼。','We had to lug / the heavy generator / up two flights of stairs / because the service lift was broken.','lug 作及物动词，表示费力地搬运笨重物品；up 引出方向。','重型发电机被费力搬上楼，符合 s1。'),C('lug.s2','机械零件','The mechanic tightened the lug on the wheel before lowering the car from the jack.','技师在把汽车从千斤顶上放下前，拧紧了车轮上的凸耳螺母。','The mechanic tightened / the lug on the wheel / before lowering the car / from the jack.','机械义 lug 指突出的连接件或车轮凸耳螺母。','车轮上的 lug 是固定零件，符合 s2。')],M('They lugged the empty paper bag upstairs effortlessly with one finger.','They lugged the heavy generator upstairs with both hands and considerable effort.','轻巧空袋且轻松搬动不符合 lug 的费力笨重感。'),[Q('To lug a generator upstairs is to?','carry or drag it awkwardly with effort','leave it in the lift','turn it into a wheel fitting','lug 作动词表示费力搬运。'),Q('A wheel lug is?','a projecting fastening fitting','the whole car engine','a piece of luggage','机械义 lug 是车轮上的凸出固定件。'),Q('Why did they lug the generator upstairs?','the service lift was broken','the generator weighed nothing','the stairs were moving','货梯坏了，只能费力搬运。'),Q('Which verb is closest to lug in the sentence?','haul','lull','lounge','haul 可表示费力搬运。')]);
P('luggage','Luggage comes through French from a word related to lug; it names the bags and cases carried on a journey and is normally uncountable.',[C('luggage.s1','车站寄存','Before boarding, Jo left her luggage in the station lockers and kept only a small handbag with her.','上车前，乔把行李放进车站储物柜，只随身带了一个小手提包。','Before boarding / Jo left her luggage / in the station lockers / and kept only a small handbag.','luggage 作不可数集合名词；说数量时用 pieces of luggage。','行李箱包被存放等待旅程，符合 s1。'),C('luggage.s2','托运规定','The airline weighed all the luggage together because the booking included one shared baggage allowance.','由于预订包含共享的行李额度，航空公司把所有托运行李放在一起称重。','The airline weighed / all the luggage together / because the booking included / one shared baggage allowance.','luggage 也可把一批箱包作为整体物品看待；通常不直接加复数词尾。','整批箱包作为一个集合称重。')],M('She packed three luggages for the trip, each inside a separate suitcase.','She packed three pieces of luggage for the trip.','luggage 通常不可数，数量表达用 pieces of luggage。','countability'),[Q('Luggage means?','bags and cases carried on a journey','the price of a train ticket','a lowland plant','luggage 指旅行携带的箱包。'),Q('Which quantity phrase is standard?','three pieces of luggage','three luggages','three luggage','luggage 通常不可数，pieces of 可表达数量。','countability'),Q('Where did Jo leave her luggage?','in station lockers','on the roof of a moving lorry','at a lottery desk','她把行李放在车站储物柜里。'),Q('Luggage most often refers to items used for?','travel','lubrication','lunar observation','行李是旅行时携带的箱包。')]);
P('lukewarm','Lukewarm combines luke (“moderately warm”) and warm; literally it means neither hot nor cold, and figuratively it means unenthusiastic.',[C('lukewarm.s1','饮品温度','The tea was only lukewarm by the time it reached the table, so the server offered to replace it.','茶送到桌上时已经只是温温的了，因此服务员提出给她换一杯。','The tea was only lukewarm / by the time it reached the table / so the server / offered to replace it.','lukewarm 作温度形容词，表示微温、不冷不热。','茶已失去热度但仍不凉，符合 s1。'),C('lukewarm.s2','观众反馈','The proposal received a lukewarm response from staff, who raised no objection but showed little enthusiasm.','员工对提案反应冷淡；他们没有反对，却也没表现出多少热情。','The proposal received / a lukewarm response / from staff / who raised no objection but showed little enthusiasm.','比喻用法 lukewarm 修饰 response，表示兴趣或赞同不强。','员工没有积极支持，符合 s2。')],M('The audience gave a lukewarm response, cheering wildly and asking to hear the proposal again.','The audience gave a lukewarm response, listening politely but showing little interest.','热烈欢呼和要求重听显示热情，不是冷淡反应。'),[Q('Lukewarm tea is?','only mildly warm','boiling hot','frozen solid','字面义是不冷不热、微温。'),Q('A lukewarm response shows?','little enthusiasm','strong excitement','complete physical warmth','比喻义表示反应冷淡、缺乏热情。'),Q('Which context uses the figurative sense?','a lukewarm reception for a proposal','a lukewarm cup of tea','a lukewarm bath thermometer','response/reception 描述态度时为比喻义。'),Q('Why did the server offer to replace the tea?','it was no longer hot enough','it was too cold to be liquid','the tea had become a suitcase','茶只剩微温，客人可能想要热茶。')]);
P('lull','Lull is probably imitative in origin; as a verb it can soothe someone or temporarily become calmer, and as a noun it is a brief quiet interval.',[C('lull.s1','婴儿入睡','Her father lulled the baby to sleep by humming softly and rocking the cradle.','她父亲轻声哼唱并摇动摇篮，把婴儿哄睡了。','Her father lulled the baby to sleep / by humming softly / and rocking the cradle.','lull someone to sleep 是常见结构，表示安抚某人入睡。','哼唱和摇篮动作使婴儿平静入睡，符合 s1。'),C('lull.s2','风势变化','The wind lulled for a few minutes, allowing the crew to secure the loose cover before the storm returned.','风势减弱了几分钟，船员趁风暴回来前固定住松脱的罩布。','The wind lulled / for a few minutes / allowing the crew / to secure the loose cover.','lull 可作不及物动词，表示暂时变平静或减弱。','风短暂平息后又会回来，符合 s2。'),C('lull.s3','活动间歇','During a lull in the traffic, the pedestrians crossed the quiet side street.','车流暂时稀少时，行人穿过了安静的支路。','During a lull in the traffic / the pedestrians crossed / the quiet side street.','a lull in something 指活动、噪音或事件短暂减少的间歇。','车流间歇变少，形成短暂空档。')],M('The storm lulled the crew by growing steadily stronger and never giving them a quiet moment.','The storm lulled briefly when the wind weakened, giving the crew a short quiet interval.','持续增强且没有平静间隔与 lull 的“暂歇”含义相反。'),[Q('To lull a baby to sleep is to?','soothe the baby until it sleeps','carry the baby awkwardly','wake the baby with a loud alarm','lull someone to sleep 表示安抚其入睡。'),Q('When the wind lulled, it?','became calmer for a short time','grew louder without stopping','changed into luggage','lull 可表示暂时减弱或平息。'),Q('A lull in traffic is?','a brief period with fewer vehicles','the loudest hour of the day','a vehicle carrying goods','a lull 指短暂的活动间歇。'),Q('Which sentence uses lull as a noun?','A lull in the rain let us leave.','The rain lull the roof yesterday.','She lulled the rain asleep.','a lull in the rain 中 lull 是间歇名词。','grammar')]);
P('lullaby','Lullaby combines lull with bye, a traditional soothing song sung to settle a child to sleep.',C('lullaby.s1','睡前习惯','Each night, her grandmother sang the same lullaby until the child’s eyes closed and her breathing slowed.','每天晚上，祖母都会唱同一首摇篮曲，直到孩子闭上眼睛、呼吸渐渐平稳。','Each night / her grandmother sang / the same lullaby / until the child’s eyes closed.','lullaby 作可数名词；sing a lullaby 表示唱催眠曲。','轻柔歌曲帮助孩子入睡，符合 s1。'),M('The parent chose a loud marching song as a lullaby to keep the baby awake all night.','The parent sang a soft lullaby to help the baby settle and fall asleep.','让婴儿整夜清醒的激昂歌曲不符合催眠曲的用途。'),[Q('A lullaby is a song meant to?','soothe someone, often a baby, to sleep','announce a lottery winner','teach a lorry driver directions','lullaby 是帮助孩子安睡的轻柔歌曲。'),Q('Who sang the lullaby in the example?','the grandmother','the child’s bus driver','a loudspeaker operator','语境中由祖母唱摇篮曲。'),Q('Which verb commonly goes with lullaby?','sing','lower','lug','常见搭配是 sing a lullaby。','collocation'),Q('How did the child respond?','her eyes closed and breathing slowed','she began shouting at the singer','she drove away in a lorry','入睡迹象是闭眼、呼吸变慢。')]);
P('lumber','Lumber is the North American term for wood sawn and prepared for building; its deeper history is uncertain, so no root is asserted.',C('lumber.s1','木材采购','The builders ordered treated lumber for the deck and checked that each board was straight and dry.','建筑工人订购了经过处理的木材用于露台，并检查每块木板是否笔直、干燥。','The builders ordered / treated lumber for the deck / and checked / that each board was straight and dry.','lumber 在美式英语常指建筑用木材；英式英语常用 timber。','处理过的木板用于建筑，符合 s1。'),M('The builders ordered lumber, a set of metal hinges and glass panes with no wood in the shipment.','The builders ordered lumber, the prepared wood needed to frame the deck.','只有金属和玻璃的货物不是 lumber。'),[Q('In North American English, lumber is?','wood prepared for building','a musical lullaby','a light skin cream','lumber 指建筑用的锯制木材。'),Q('What did the builders use it for?','the deck','a lottery drawing','a hospital lung scan','木材订来建造露台。'),Q('Which word is common in British English for building wood?','timber','luggage','lucre','英式英语常用 timber。'),Q('What did they inspect on each board?','that it was straight and dry','that it was loud and loyal','that it carried a lottery number','工人检查木板的直度与干燥程度。')]);
P('lumbering','Lumbering comes from lumber and names the work of cutting and moving timber; as an adjective it describes slow, awkward movement.',[C('lumbering.s1','林业运输','Lumbering expanded along the river because logs could be floated downstream to the mills.','由于原木可以顺流漂到木材厂，沿河的伐木业逐渐扩大。','Lumbering expanded / along the river / because logs could be floated / downstream to the mills.','lumbering 作不可数名词，指伐木和木材运输行业。','原木采伐并运往木材厂体现林业活动。'),C('lumbering.s2','动物动作','The bear made a lumbering turn through the narrow gate, moving slowly because of its size.','熊笨重地转过狭窄的门，因为体型庞大而动作缓慢。','The bear made / a lumbering turn / through the narrow gate / moving slowly because of its size.','lumbering 作形容词，形容体型大导致动作迟缓笨拙。','缓慢笨重的转身符合 s2。')],M('The small dancer made a lumbering turn, moving lightly and quickly through the narrow gate.','The large bear made a lumbering turn, moving slowly and awkwardly through the gate.','轻快敏捷的动作不符合 lumbering 的笨重义。'),[Q('Lumbering along a river refers to?','the work of cutting and moving timber','a formal midday meal','the measurement of sound','名词 lumbering 指伐木业及木材搬运。'),Q('A lumbering bear moves?','slowly and awkwardly','lightly and rapidly','silently in a straight line','形容词义描写庞大动物动作迟缓笨重。'),Q('Why were logs floated downstream?','to transport them to mills','to make them into luggage','to cool them for lunch','顺流漂木材可运到下游木材厂。'),Q('Which is an adjective use?','a lumbering movement','the lumbering industry grew','lumbering is timber work','lumbering 可形容缓慢笨重的动作。')]);
P('luminosity','Luminosity comes from Latin luminositas, from lumen (“light”); it is the brightness emitted by an object, especially a star.',C('luminosity.s1','天文学观测','Astronomers compared the star’s luminosity with its apparent size to estimate how much energy it emitted.','天文学家把恒星的亮度与视观大小进行比较，以估算它发出的能量。','Astronomers compared / the star’s luminosity / with its apparent size / to estimate how much energy it emitted.','luminosity 作不可数科学名词，天文学中常指恒星本身的发光强度。','对恒星辐射能量的估算依赖其内禀亮度。'),M('The star’s luminosity was described as high even though it emitted no light or energy.','The star’s luminosity was high because it emitted a great amount of light energy.','不发光就没有高亮度可测。'),[Q('A star’s luminosity refers to?','its intrinsic brightness or emitted light','its distance from the nearest road','the size of its luggage','luminosity 指天体本身的发光亮度。'),Q('What did astronomers compare it with?','the star’s apparent size','the star’s lunch time','the colour of a loudspeaker','例句说天文学家结合视观大小估算能量。'),Q('Luminosity is related to which word?','luminous','loutish','luggage','luminosity 与 luminous 都和光有关。','word-formation'),Q('Which field often measures stellar luminosity?','astronomy','carpentry','tennis scoring','恒星亮度是天文学研究量。')]);
P('luminous','Luminous comes from Latin luminosus, from lumen (“light”); it means producing or shining with light and can describe clear, brilliant writing.',[C('luminous.s1','夜间标记','The luminous strip on the life jacket remained visible after the cabin lights were switched off.','客舱灯关掉后，救生衣上的夜光条仍然清晰可见。','The luminous strip / on the life jacket / remained visible / after the cabin lights were switched off.','luminous 修饰 strip，表示能发光或在暗处可见。','黑暗中仍可见的标记符合 s1。'),C('luminous.s2','文学评论','The essay offered a luminous account of the migration, making a complex history vivid and easy to follow.','这篇文章对迁徙作了明晰生动的叙述，使复杂历史鲜活而易于理解。','The essay offered / a luminous account / of the migration / making a complex history vivid and easy to follow.','文学义 luminous 可形容表达清晰、明亮而令人印象深刻的文字。','文章让复杂历史变得清楚生动，符合 s2。')],M('The luminous marker disappeared completely in darkness and could not be seen after the lights went out.','The luminous marker continued to shine or remain visible after the lights went out.','灯灭后完全不可见不符合 luminous。'),[Q('A luminous strip is?','glowing or visible in the dark','heavy enough to carry a person','a type of lunch','luminous 表示发光、夜光。'),Q('A luminous account in writing is?','clear, vivid, and impressive','confused and impossible to follow','a literal source of lamp oil','文学比喻义描述清晰明亮的文字。'),Q('What happened after the cabin lights went out?','the strip remained visible','the jacket became a loudspeaker','the passengers lost their lunch','夜光条仍可见。'),Q('Which phrase is natural?','luminous writing','luminous of writing','writing luminary','luminous 可修饰写作或叙述。','grammar')]);
P('lump','Lump has uncertain deeper origins; it can mean an irregular solid piece, a swelling under the skin, or the verb of treating unlike things as one group.',[C('lump.s1','烘焙配料','Sift the flour before mixing so no dry lumps remain in the cake batter.','混合前先筛面粉，这样蛋糕面糊里就不会残留干面团块。','Sift the flour / before mixing / so no dry lumps / remain in the cake batter.','lump 作可数名词，a lump of 指无规则的一块或一团。','面粉结成的干团块符合 s1。'),C('lump.s2','健康咨询','The nurse advised him to have the new lump in his neck checked rather than guessing what caused it.','护士建议他检查颈部新出现的肿块，而不是猜测原因。','The nurse advised him / to have the new lump / in his neck checked / rather than guessing what caused it.','lump 可指身体组织下的硬肿块；医学语境中应检查，不自行诊断。','颈部新出现的隆起符合 s2。'),C('lump.s3','统计分类','The report wrongly lumped rural and urban households together even though their transport needs differed.','报告错误地把农村和城市家庭混为一类，尽管两者的交通需求不同。','The report wrongly lumped / rural and urban households together / even though / their transport needs differed.','lump A and B together 表示把不同事物当作同一类处理。','报告将需求不同的群体合并，符合 s3。')],M('The report lumped the two groups together even though it carefully analysed them separately and never combined their results.','The report lumped the groups together by treating their different needs as if they were the same.','分别分析而没有合并，不构成 lump together。'),[Q('A lump of flour is?','an irregular solid mass','a smooth liquid with no pieces','a loud announcement','lump 可指无规则的一团或一块。'),Q('A lump under the skin is?','a hard swelling that should be checked','a standard meal at noon','a lowland plant','身体义 lump 指皮下肿块。'),Q('To lump groups together is to?','treat them as one despite differences','measure each group separately','help them reach a higher place','lump together 指把不同对象归为一类。'),Q('Which phrase is natural?','lump two categories together','lump together two categories’ apart','a lumply category','常见结构为 lump A and B together。','collocation')]);
P('lunar','Lunar comes from Latin lunaris, from luna (“moon”); it describes something related to the Moon or measured by its cycles.',[C('lunar.s1','天文观测','The lunar surface looked sharply lit through the telescope, revealing ridges along the edge of a crater.','通过望远镜，月球表面看起来光照清晰，能看到陨石坑边缘的山脊。','The lunar surface looked sharply lit / through the telescope / revealing ridges / along the edge of a crater.','lunar 作形容词，修饰与月球有关的名词。','陨石坑是月球表面特征，符合 s1。'),C('lunar.s2','历法安排','The festival date follows a lunar calendar, so it shifts relative to the solar calendar each year.','节日日期遵循阴历，因此每年相对于阳历都会发生变化。','The festival date follows / a lunar calendar / so it shifts / relative to the solar calendar each year.','lunar calendar 按月相或月亮运行计算月份。','日期随月亮周期而变化，符合 s2。')],M('The observatory called it a lunar eclipse even though the Moon was not involved and only the Sun was visible.','The observatory called it a lunar eclipse because the event involved the Moon passing into Earth’s shadow.','没有月球参与的现象不是月食。'),[Q('The lunar surface is the surface of?','the Moon','a lowland forest','a lorry','lunar 表示与月球有关。'),Q('A lunar calendar is based on?','the Moon’s cycles','the Earth’s road network','a lottery schedule','lunar calendar 按月亮周期安排日期。'),Q('Why does the festival date shift each year?','it follows a lunar rather than solar calendar','it is chosen by a loudspeaker','it is measured by luggage weight','阴历日期相对阳历会逐年移动。'),Q('Which phrase is natural?','lunar mission','lunarly mission','lunarize mission','lunar 作形容词修饰 mission。','grammar')]);
P('lunatic','Lunatic derives through Latin lunaticus (“affected by the Moon”), reflecting an old belief about madness; the noun is now often offensive, while the adjective can mean wildly foolish.',[C('lunatic.s1','历史文献','The historian noted that an old court record used “lunatic” as a label, but modern writers avoid applying it to people.','历史学家指出，旧法庭记录曾用“lunatic”作标签，但现代作者避免用它称呼他人。','The historian noted / that an old court record used “lunatic” / as a label / but modern writers avoid applying it to people.','名词 lunatic 是过时且可能冒犯的称呼，只宜在引述旧文献时说明。','文献例子明确是历史用词而非现代称呼。'),C('lunatic.s2','风险评论','Driving down the icy hill without brakes was a lunatic decision, and the team stopped the test immediately.','在结冰的山坡上不带刹车开车是个极其荒唐的决定，团队立刻叫停了测试。','Driving down the icy hill without brakes / was a lunatic decision / and the team / stopped the test immediately.','口语形容词 lunatic 可表示极其愚蠢或鲁莽；用于人时需谨慎。','无刹车在冰坡测试明显鲁莽，符合 s2。')],M('The editor described the historical term as a polite modern label that is harmless to use for anyone.','The editor warned that the historical noun can offend and should not be used casually for people.','该名词如今常有冒犯性，不应说成无害礼貌用语。','register'),[Q('Why does the historian quote “lunatic”?','to discuss an old court record’s wording','to recommend a polite modern label','to describe the Moon’s surface','这里是分析历史文献中的旧称。'),Q('A lunatic decision is?','wildly foolish or reckless','carefully safe and well planned','a lunar calendar date','形容词义表示荒唐、鲁莽。'),Q('How should the noun lunatic be treated today?','as potentially offensive, especially when applied to people','as the preferred neutral medical term','as a word for a lucky person','该名词可能冒犯，不是中性诊断术语。'),Q('Which situation could be called lunatic in the adjective sense?','driving on ice without brakes','checking a map before travelling','wearing a life jacket on a boat','缺刹车在冰面行驶是极其鲁莽的决定。')]);
P('lunch','Lunch is probably a shortening of luncheon; it names the midday meal and can also be a verb meaning to eat that meal.',[C('lunch.s1','午间休息','We packed sandwiches for lunch because the museum café was closed on Mondays.','由于博物馆咖啡馆周一不开门，我们带了三明治当午餐。','We packed sandwiches / for lunch / because the museum café / was closed on Mondays.','lunch 作可数名词，表示一天中间的正餐；for lunch 表用途或餐次。','三明治作为午间一餐，符合 s1。'),C('lunch.s2','商务约见','The directors lunched together after the morning briefing to discuss the new contract.','早间简报后，董事们一起吃午餐并讨论新合同。','The directors lunched together / after the morning briefing / to discuss the new contract.','lunch 也可作动词；lunch with someone 表示与某人共进午餐。','董事们边用午餐边讨论合同，符合动词义 s2。')],M('The directors lunched together by skipping the midday meal and refusing to eat anything.','The directors lunched together by sharing a midday meal after the briefing.','不吃午饭不能称为 lunched。'),[Q('What did they pack for lunch?','sandwiches','lumber','a loudspeaker','三明治是他们带去当午餐的食物。'),Q('“The directors lunched together” means they?','ate the midday meal together','played tennis to a score of love','carried luggage upstairs','lunch 作动词表示吃午餐。'),Q('Why did they bring their own food?','the museum café was closed','the café offered too many meals','they had no bags','咖啡馆周一关门，所以他们自带食物。'),Q('Which phrase is natural?','have lunch together','make a lunch to someone','lunching the sandwiches down','常用表达为 have lunch together。','collocation')]);
P('luncheon','Luncheon is a formal or literary word for lunch, often a planned midday meal or gathering.',C('luncheon.s1','慈善活动','The museum hosted a fundraising luncheon for donors in its restored courtyard.','博物馆在修复后的庭院里为捐赠者举办了一场筹款午餐会。','The museum hosted / a fundraising luncheon / for donors / in its restored courtyard.','luncheon 作可数名词，语域较正式，常与 fundraising/charity 连用。','为捐赠者举办的正式筹款午餐会符合 s1。'),M('The invitation called it a luncheon, but it was a midnight dance with no meal or gathering at midday.','The invitation called it a luncheon because guests would meet for a formal midday meal.','午夜舞会且没有午餐，不符合 luncheon。'),[Q('A luncheon is usually?','a formal midday meal or gathering','a late-night vehicle repair','a type of lunar calendar','luncheon 是较正式的午餐或午餐会。'),Q('Why did the museum host it?','to raise funds from donors','to measure star luminosity','to locate lost luggage','这场午餐会用于筹款。'),Q('Which word has the more formal register?','luncheon','lunchbox','loudly','luncheon 比 lunch 正式。','register'),Q('Which phrase is natural?','a fundraising luncheon','a luncheoning very early','a luncheon of the loud','fundraising luncheon 是自然搭配。','collocation')]);
P('lunchtime','Lunchtime combines lunch and time and means the part of the day when people usually eat lunch.',C('lunchtime.s1','学校作息','At lunchtime, the pupils ate in the courtyard because the dining hall was being cleaned.','午餐时间，学生们在庭院里用餐，因为食堂正在清洁。','At lunchtime / the pupils ate in the courtyard / because the dining hall / was being cleaned.','lunchtime 作不可数时间名词，常置于介词 at 之后。','学生在午间用餐，符合 s1。'),M('The pupils left for lunchtime at midnight, although their school schedule placed it in the middle of the day.','The pupils left for lunch at lunchtime, the part of the day set aside for the midday meal.','午夜与学校安排的午餐时间不符。'),[Q('Lunchtime is?','the part of the day when people eat lunch','the hour when people usually sleep at night','a type of lunch container','lunchtime 指午餐时间。'),Q('Where did the pupils eat?','in the courtyard','in the station lost-and-found','inside a luggage locker','食堂清洁时他们在庭院吃饭。'),Q('Which preposition commonly comes before lunchtime?','at','from of','by into','常说 at lunchtime。','collocation'),Q('Why were they outside?','the dining hall was being cleaned','the courtyard had a luminous roof','the teacher wanted a lottery','语境说食堂正在清洁。')]);
P('lung','Lung comes from Old English lungen and names one of the paired organs in the chest used for breathing.',[C('lung.s1','健康检查','The doctor listened to each lung while the patient took slow, steady breaths.','病人缓慢而平稳地呼吸时，医生听诊了每一侧肺部。','The doctor listened / to each lung / while the patient / took slow, steady breaths.','lung 作可数名词，each lung 指一对器官中的一侧。','医生听诊胸腔内负责呼吸的器官。'),C('lung.s2','呼吸系统','Smoking can damage the lungs, the pair of organs that bring oxygen into the body.','吸烟会损害肺部；这对器官负责将氧气带入身体。','Smoking can damage the lungs / the pair of organs / that bring oxygen / into the body.','lungs 常用复数指左右肺这一对呼吸器官。','复数指作为一对的呼吸器官。')],M('The doctor said the lungs pump blood through the body while the heart takes oxygen from the air.','The doctor said the lungs take oxygen from air while the heart pumps blood.','肺负责气体交换；泵血的是心脏。'),[Q('What does a lung help a person do?','breathe','hear low sounds','digest luggage','lung 是呼吸器官。'),Q('How many lungs do people normally have?','two','one hundred','none','人体通常有左右两侧两只肺。'),Q('What did the doctor listen to?','each lung as the patient breathed','the patient’s lunch order','a luminous star','医生在病人呼吸时听诊肺部。'),Q('Which organ pumps blood rather than taking oxygen from air?','the heart','the lung','the liver’s lunch','心脏负责泵血，肺负责呼吸气体交换。')]);
P('lunge','Lunge comes through French, originally a fencing term, and means to make a sudden forceful forward movement.',C('lunge.s1','击剑训练','The fencer lunged toward the target with her front foot while keeping the rear leg straight.','击剑手前脚向目标猛跨，同时保持后腿伸直。','The fencer lunged / toward the target / with her front foot / while keeping the rear leg straight.','lunge 作不及物动词，常接 toward/at；也可作一次突然前冲的名词。','击剑中的突然向前进攻符合 s1。'),M('The fencer lunged by stepping slowly backward and never moving toward the target.','The fencer lunged by making a sudden forward attack toward the target.','缓慢后退不是向前猛冲。'),[Q('The fencer lunged toward the target by?','making a sudden forward move','walking slowly backward','sitting down quietly','lunge 指突然向前猛冲。'),Q('Which sport is associated with the historical term?','fencing','luncheon service','luggage handling','lunge 最初与击剑术语相关。'),Q('Which preposition fits the example?','toward','beneath of','despite to','常说 lunge toward/at a target。','grammar'),Q('A lunge can be?','a sudden forward movement','a formal midday meal','an old word for a pike','lunge 也可作名词，指一次猛冲。')]);
P('lurch','Lurch is a verb and noun for a sudden unsteady tilt or stagger; its deeper origin is uncertain.',[C('lurch.s1','船只遇浪','The ferry gave a sudden lurch when a large wave struck its side.','大浪拍打船身时，渡船突然猛烈一晃。','The ferry gave / a sudden lurch / when a large wave / struck its side.','lurch 作可数名词，a lurch 表示突然倾斜或摇晃。','船身被浪冲得突然不稳，符合 s1。'),C('lurch.s2','醉酒步态','The exhausted hiker lurched along the path, taking uneven steps as he struggled to stay upright.','筋疲力尽的徒步者沿小路蹒跚前行，步伐不稳，努力保持站立。','The exhausted hiker lurched / along the path / taking uneven steps / as he struggled to stay upright.','lurch 作不及物动词，常接 along，描述不稳地蹒跚移动。','不规则步伐和摇晃行走符合 s2。')],M('The ferry lurched smoothly and steadily with no sudden tilt or movement.','The ferry lurched sharply when the wave struck and threw passengers off balance.','平稳无晃动不符合 lurch 的突然倾斜。'),[Q('A ferry’s lurch is?','a sudden unsteady tilt or movement','a smooth, motionless pause','a low meal eaten at noon','lurch 名词指突然不稳的一晃。'),Q('The hiker lurched along the path by?','taking uneven, unsteady steps','running smoothly in a straight line','sitting still by the water','动词义指步态摇晃、不稳地移动。'),Q('What made the ferry lurch?','a large wave struck its side','the crew served lunch','the route passed a lowland','船被大浪拍击后突然摇晃。'),Q('Which word is closest to the walking sense of lurch?','stagger','lull','lounge','stagger 同样表示蹒跚不稳地走。')]);
P('lure','Lure came through French leurre, originally a decoy used in falconry; it means to attract someone by an appealing offer or to name the attraction itself.',[C('lure.s1','网络诈骗','The scam email tried to lure shoppers to a fake website by promising a prize that did not exist.','诈骗邮件承诺一个根本不存在的奖品，试图把购物者诱骗到假网站。','The scam email tried / to lure shoppers / to a fake website / by promising a prize that did not exist.','lure 作及物动词，lure someone to/into a place or action，常带欺骗意味。','虚假奖品被用来引诱购物者访问假网站。'),C('lure.s2','旅游吸引力','The island’s main lure is its quiet coastline, which attracts visitors seeking an escape from crowded cities.','这座岛最主要的吸引力是安静的海岸线，它吸引想逃离拥挤城市的游客。','The island’s main lure / is its quiet coastline / which attracts visitors / seeking an escape from crowded cities.','lure 作名词可指吸引人的特质或诱惑力。','宁静海岸吸引游客，符合 s2。'),C('lure.s3','垂钓工具','The angler attached a bright lure to the line to attract fish near the shaded bank.','钓鱼者把一枚鲜艳的鱼饵系在线上，以吸引阴凉岸边的鱼。','The angler attached / a bright lure / to the line / to attract fish near the shaded bank.','lure 也作可数名词，指用于吸引鱼或动物的诱饵。','人工鱼饵用于吸引鱼类，符合 s3。')],M('The email lured shoppers to the fake site by honestly warning them that no prize existed.','The email lured shoppers to the fake site by falsely promising them a valuable prize.','诚实地警告没有奖品，不会起到欺骗引诱作用。'),[Q('How did the scam email lure shoppers?','it promised a prize that did not exist','it clearly warned them away from the site','it delivered their real luggage','虚假奖品被用来引诱受害者。'),Q('The island’s lure is its coastline means the coastline is?','an appealing feature that attracts visitors','a machine for reducing friction','a place where fish are forbidden','lure 名词可指吸引人的特质。'),Q('A fishing lure is?','an object used to attract fish','a formal lunch meeting','a piece of timber','鱼饵用于吸引鱼类。'),Q('Which phrase is natural?','lure someone into a trap','lure someone at a promise','lure the visitor of the beach','常见搭配为 lure someone into/to something。','collocation')]);

})();
